@Test
public void testConstructingUserHomeDirectory() throws Exception {
    String[] sources = new String[] { "output+", "/user/hadoop/output", "hdfs://container", "hdfs://container/", "hdfs://container/path", "output#link", "hdfs://cointaner/output#link", "hdfs://container@acc/test", "/user/webhcat/düsseldorf", "düsseldorf", "䶴狝A﨩O", "hdfs://host:8080" };
    String[] expectedResults = new String[] { "/user/webhcat/output+", "/user/hadoop/output", "hdfs://container/user/webhcat", "hdfs://container/", "hdfs://container/path", "/user/webhcat/output#link", "hdfs://cointaner/output#link", "hdfs://container@acc/test", "/user/webhcat/düsseldorf", "/user/webhcat/düsseldorf", "/user/webhcat/䶴狝A﨩O", "hdfs://host:8080/user/webhcat" };
    for (int i = 0; i < sources.length; i++) {
        String source = sources[i];
        String expectedResult = expectedResults[i];
        String result = TempletonUtils.addUserHomeDirectoryIfApplicable(source, "webhcat");
        Assert.assertEquals("i=" + i, expectedResult, result);
    }
    String badUri = "c:\\some\\path";
    try {
        TempletonUtils.addUserHomeDirectoryIfApplicable(badUri, "webhcat");
        Assert.fail("addUserHomeDirectoryIfApplicable should fail for bad URI: " + badUri);
    } catch (IllegalArgumentException ex) {
    }
}

@Test
public void testPropertiesParsing() throws Exception {
    String[] props = { "hive.metastore.uris=thrift://localhost:9933\\,thrift://127.0.0.1:9933", "hive.metastore.sasl.enabled=false", "hive.some.fake.path=C:\\foo\\bar.txt\\" };
    StringBuilder input = new StringBuilder();
    for (String prop : props) {
        if (input.length() > 0) {
            input.append(',');
        }
        input.append(prop);
    }
    String[] newProps = StringUtils.split(input.toString());
    for (int i = 0; i < newProps.length; i++) {
        Assert.assertEquals("Pre/post split values don't match", TempletonUtils.unEscapeString(props[i]), TempletonUtils.unEscapeString(newProps[i]));
    }
}

