    table.removeAt(1);
    assertEquals(Arrays.asList(5, 4, 3), collectKeysBackward(table));
    table.removeFromTo(4, 5);
    assertEquals(Arrays.asList(3), collectKeysBackward(table));
    table.removeAt(3);
    assertEquals(Collections.emptyList(), collectKeysBackward(table));
}

