    List<FieldSchema> hmsSchema = hmsTable.getSd().getCols();
    List<FieldSchema> expectedSchema = Lists.newArrayList(// customer_id: type promotion (int -> bigint), no change in comment
    new FieldSchema("customer_id", "bigint", null), // first_name column is dropped
