    new FieldSchema("last_name", "string", "This is last name"), // address: comment added, no change in type
    new FieldSchema("address", "struct<city:string,street:string>", "Adding some comment"), // new_col: brand new column
    new FieldSchema("new_col", "string", "This is a new column added"));
