@Test
public void testCTASPartitionedFromHiveTable() throws TException, InterruptedException {
    Assume.assumeTrue(HiveIcebergSerDe.CTAS_EXCEPTION_MSG, testTableType == TestTables.TestTableType.HIVE_CATALOG);
    shell.executeStatement("CREATE TABLE source (id bigint, name string) PARTITIONED BY (dept string) STORED AS ORC");
    shell.executeStatement(testTables.getInsertQuery(HiveIcebergStorageHandlerTestUtils.CUSTOMER_RECORDS, TableIdentifier.of("default", "source"), false));
    shell.executeStatement(String.format("CREATE TABLE target PARTITIONED BY (dept, name) " + "STORED BY ICEBERG TBLPROPERTIES ('%s'='%s') AS SELECT * FROM source", TableProperties.DEFAULT_FILE_FORMAT, fileFormat));
