public void testInsertEventReplay() throws Throwable {
    // Do an empty dump & load to move to incremental mode.
    WarehouseInstance.Tuple tuple = primary.dump(primaryDbName);
    replica.load(replicatedDbName, primaryDbName).run("use " + replicatedDbName).run("repl status " + replicatedDbName).verifyResult(tuple.lastReplicationId);
