    // Reset the logger
    appender.reset();
    replica.load(replicatedDbName, primaryDbName).run("use " + replicatedDbName).run("select id from t1").verifyResults(new String[] { "1", "2" });
    assertTrue(appender.getOutput(), appender.getOutput().contains("Loading event EVENT_INSERT"));
    // Drop & create a table with different schema.
    tuple = primary.run("use " + primaryDbName).run("drop table t1").run("create table t1 (name string)").run("insert into table t1 values ('one'),('two')").dump(primaryDbName);
    replId = Integer.parseInt(tuple.lastReplicationId) - 3;
