    // Reset the logger
    appender.reset();
    replica.load(replicatedDbName, primaryDbName).run("use " + replicatedDbName).run("select name from t1").verifyResults(new String[] { "one", "two" });
    assertTrue(appender.getOutput(), appender.getOutput().contains("Loading event EVENT_INSERT"));
}

