        outputStream.write("15,27\n".getBytes());
    }
    ReplicationMigrationTool replTool = new ReplicationMigrationTool();
    verifyFailures(tuple, replTool, "Directory Size mismatch", "Extra entry at source", "Extra entry at source");
    // Do a dump & load cycle so that source & target are again in sync, the script should return success.
    tuple = doAnEmptyDumpAndLoadCycle(withClause);
    verifySuccessfulResult(tuple);
    // Now delete one file at source & do a verification.
    fs.delete(new Path(externalTableLocation, "file1.txt"), true);
    verifyFailures(tuple, replTool, "Directory Size mismatch", "Source Or Target has an extra/less files", "Source Or Target has an extra/less files.");
    // Do a dump & load cycle so that source & target are again in sync, the script should return success.
    tuple = doAnEmptyDumpAndLoadCycle(withClause);
    verifySuccessfulResult(tuple);
}

@Test
public void testModifiedContentAndOpenFiles() throws Throwable {
    List<String> withClause = ReplicationTestUtils.includeExternalTableClause(true);
    Path externalTableLocationa = new Path("/" + testName.getMethodName() + "/" + primaryDbName + "/" + "a/");
    DistributedFileSystem fs = primary.miniDFSCluster.getFileSystem();
    fs.mkdirs(externalTableLocationa, new FsPermission("777"));
    Path externalTableLocationb = new Path("/" + testName.getMethodName() + "/" + primaryDbName + "/" + "b");
    fs.mkdirs(externalTableLocationb, new FsPermission("777"));
    //externally add data to location
    try (FSDataOutputStream outputStream = fs.create(new Path(externalTableLocationa, "filea1.txt"))) {
        outputStream.write("1,2\n".getBytes());
        outputStream.write("13,21\n".getBytes());
    }
    try (FSDataOutputStream outputStream = fs.create(new Path(externalTableLocationb, "fileb1.txt"))) {
        outputStream.write("1,2\n".getBytes());
        outputStream.write("13,21\n".getBytes());
    }
    WarehouseInstance.Tuple tuple = primary.run("use " + primaryDbName).run("create external table tablea (i int, j int) row format delimited fields terminated by ',' " + "location '" + externalTableLocationa.toUri() + "'").run("create external table tableb (i int, j int) row format delimited fields terminated by ',' " + "location '" + externalTableLocationb.toUri() + "'").run("insert into table tableb values (25,26)").run("insert into table tableb values (28,29),(36,37),(42,43)").dump(primaryDbName, withClause);
    replica.load(replicatedDbName, primaryDbName, withClause).run("use " + replicatedDbName).verifyReplTargetProperty(replicatedDbName);
    // Everything is in sync, script should return success.
    verifySuccessfulResult(tuple);
    // Alter the content of one of the file, keeping the bytes same
    try (FSDataOutputStream outputStream = fs.create(new Path(externalTableLocationb, "fileb1.txt"))) {
        outputStream.write("1,4\n".getBytes());
        outputStream.write("13,21\n".getBytes());
    }
    // All other checks shall falsely pass, the checksum verification, should catch and fail.
    ReplicationMigrationTool replTool = new ReplicationMigrationTool();
    validateChecksumValidationFails(replTool, tuple, "File Checksum mismatch");
    // Do a dump & load cycle and check everything should be in sync.
    tuple = doAnEmptyDumpAndLoadCycle(withClause);
    verifySuccessfulResult(tuple);
    // Modify the content of a file without keeping the number of bytes same.
    try (FSDataOutputStream outputStream = fs.create(new Path(externalTableLocationa, "filea1.txt"))) {
        outputStream.write("1,2\n".getBytes());
        outputStream.write("13,21\n".getBytes());
        outputStream.write("25,50\n".getBytes());
    }
    validateFileLevelValidationFails(replTool, tuple, "File Size mismatch");
    validateChecksumValidationFails(replTool, tuple, "File Size mismatch");
    // Do a dump & load cycle and check everything should be in sync.
    tuple = doAnEmptyDumpAndLoadCycle(withClause);
    verifySuccessfulResult(tuple);
    // Open a file and check if it gets caught by the verify open file option.
    FSDataOutputStream stream = fs.append(new Path(externalTableLocationa, "filea1.txt"));
    ToolRunner.run(conf, replTool, new String[] { "-dumpFilePath", tuple.dumpLocation, "-fileLevelCheck", "-verifyOpenFiles" });
    fail("Script didn't fail despite having an open file.");
    // Make sure we get the exception.
    assertTrue(err.toString(), err.toString().contains("There are open files"));
    err.reset();
    out.reset();
    // Confirm that successful message is not printed, and failure message is printed.
    assertFalse(out.toString(), out.toString().contains("Completed verification. Source & Target are in Sync."));
    assertTrue(out.toString(), out.toString().contains("Completed verification. Source & Target are not in Sync."));
    // Close the file and check, the script should return success.
    stream.close();
    verifySuccessfulResult(tuple);
}

@Test
public void testFilters() throws Throwable {
    List<String> withClause = ReplicationTestUtils.includeExternalTableClause(true);
    Path externalTableLocation = new Path("/" + testName.getMethodName() + "/" + primaryDbName + "/" + "a/");
    DistributedFileSystem fs = primary.miniDFSCluster.getFileSystem();
    fs.mkdirs(externalTableLocation, new FsPermission("777"));
    //externally add data to location
    try (FSDataOutputStream outputStream = fs.create(new Path(externalTableLocation, "file1.txt"))) {
        outputStream.write("1,2\n".getBytes());
        outputStream.write("13,21\n".getBytes());
    }
    // Create file & dir that needs to be filtered out.
    Path random1 = new Path(externalTableLocation, "randomStuff1");
    DFSTestUtil.createFile(fs, random1, 1024L, (short) 1, 1024L);
    Path random2 = new Path(externalTableLocation, "randomStuff2");
    DFSTestUtil.createFile(fs, random2, 1024L, (short) 1, 1024L);
    // Create a filter file for DistCp
    String filterFilePath = "/tmp/filter";
    FileWriter myWriter = new FileWriter(filterFilePath);
    myWriter.write(".*randomStuff.*");
    myWriter.close();
    withClause.add("'distcp.options.filters'='" + filterFilePath + "'");
    WarehouseInstance.Tuple tuple = primary.run("use " + primaryDbName).run("create external table tablea (i int, j int) row format delimited fields terminated by ',' " + "location '" + externalTableLocation.toUri() + "'").run("insert into table tablea values (215,226)").run("insert into table tablea values (281,229),(336,347),(542,453)").run("create external table tableb (id int)").run("insert into table tableb values (15)").run("insert into table tableb values (24),(26),(82)").dump(primaryDbName, withClause);
    replica.load(replicatedDbName, primaryDbName, withClause).run("use " + replicatedDbName).verifyReplTargetProperty(replicatedDbName);
    // Check if the filtered files didn't get copied.
    assertFalse(fs.exists(new Path(REPLICA_EXTERNAL_BASE, random1.toUri().getPath().replaceFirst("/", ""))));
    assertFalse(fs.exists(new Path(REPLICA_EXTERNAL_BASE, random2.toUri().getPath().replaceFirst("/", ""))));
    ReplicationMigrationTool replTool = new ReplicationMigrationTool();
    // Verify at file level.
    assertEquals(0, ToolRunner.run(conf, replTool, new String[] { "-dumpFilePath", tuple.dumpLocation, "-fileLevelCheck", "-filters", ".*randomStuff.*" }));
    assertTrue(out.toString(), out.toString().contains("Completed verification. Source & Target are in Sync."));
    out.reset();
    // Verify at file level, with checksum.
    assertEquals(0, ToolRunner.run(conf, replTool, new String[] { "-dumpFilePath", tuple.dumpLocation, "-fileLevelCheck", "-verifyChecksum", "-filters", ".*randomStuff.*" }));
    assertTrue(out.toString(), out.toString().contains("Completed verification. Source & Target are in Sync."));
    out.reset();
}

@Test
public void testHiveStreamingUnpartitionedWithTxnBatchSizeAsOne() throws Throwable {
    primary.dump(primaryDbName);
    replica.loadWithoutExplain(replicatedDbName, primaryDbName);
    // Create an ACID table.
    String tblName = "alerts";
    primary.run("use " + primaryDbName).run("create table " + tblName + "( id int , msg string ) " + "clustered by (id) into 5 buckets " + "stored as orc tblproperties(\"transactional\"=\"true\")");
    // Create delimited record writer whose schema exactly matches table schema
    StrictDelimitedInputWriter writer = StrictDelimitedInputWriter.newBuilder().withFieldDelimiter(',').build();
    // Create and open streaming connection (default.src table has to exist already)
    // By default, txn batch size is 1.
    StreamingConnection connection = HiveStreamingConnection.newBuilder().withDatabase(primaryDbName).withTable(tblName).withAgentInfo("example-agent-1").withRecordWriter(writer).withHiveConf(primary.getConf()).connect();
    // Begin a transaction, write records and commit 1st transaction
    connection.beginTransaction();
    connection.write("1,val1".getBytes());
    connection.write("2,val2".getBytes());
    connection.commitTransaction();
    // Replicate the committed data which should be visible.
    primary.dump(primaryDbName);
    replica.loadWithoutExplain(replicatedDbName, primaryDbName).run("use " + replicatedDbName).run("select msg from " + tblName + " order by msg").verifyResults((new String[] { "val1", "val2" }));
    // Begin another transaction, write more records and commit 2nd transaction after REPL LOAD.
    connection.beginTransaction();
    connection.write("3,val3".getBytes());
    connection.write("4,val4".getBytes());
    // Replicate events before committing txn. The uncommitted data shouldn't be seen.
    primary.dump(primaryDbName);
    replica.loadWithoutExplain(replicatedDbName, primaryDbName).run("use " + replicatedDbName).run("select msg from " + tblName + " order by msg").verifyResults((new String[] { "val1", "val2" }));
    connection.commitTransaction();
    // After commit, the data should be replicated and visible.
    primary.dump(primaryDbName);
    replica.loadWithoutExplain(replicatedDbName, primaryDbName).run("use " + replicatedDbName).run("select msg from " + tblName + " order by msg").verifyResults((new String[] { "val1", "val2", "val3", "val4" }));
    // Begin another transaction, write more records and abort 3rd transaction
    connection.beginTransaction();
    connection.write("5,val5".getBytes());
    connection.write("6,val6".getBytes());
    connection.abortTransaction();
    // Aborted data shouldn't be visible.
    primary.dump(primaryDbName);
    replica.loadWithoutExplain(replicatedDbName, primaryDbName).run("use " + replicatedDbName).run("select msg from " + tblName + " order by msg").verifyResults((new String[] { "val1", "val2", "val3", "val4" }));
    // Close the streaming connection
    connection.close();
}

