@Test
public void testCheckpointingIncrWithTableDrop() throws Throwable {
    WarehouseInstance.Tuple bootstrapDump = primary.run("use " + primaryDbName).run("CREATE TABLE t1(a string) STORED AS TEXTFILE").run("insert into t1 values (1)").run("CREATE TABLE t2(a string) STORED AS TEXTFILE").run("insert into t2 values (2)").dump(primaryDbName);
    replica.load(replicatedDbName, primaryDbName).run("select * from " + replicatedDbName + ".t1").verifyResults(new String[] { "1" }).run("select * from " + replicatedDbName + ".t2").verifyResults(new String[] { "2" });
    ReplDumpWork.testDeletePreviousDumpMetaPath(true);
    WarehouseInstance.Tuple incrementalDump1 = primary.run("use " + primaryDbName).run("CREATE TABLE t3(a string) STORED AS TEXTFILE").run("insert into t3 values (3)").run("insert into t1 values (4)").run("DROP TABLE t2").dump(primaryDbName);
    Path hiveDumpDir = new Path(incrementalDump1.dumpLocation, ReplUtils.REPL_HIVE_BASE_DIR);
    Path ackFile = new Path(hiveDumpDir, ReplAck.DUMP_ACKNOWLEDGEMENT.toString());
    Path ackLastEventID = new Path(hiveDumpDir, ReplAck.EVENTS_DUMP.toString());
    Path dumpMetaData = new Path(hiveDumpDir, "_dumpmetadata");
    FileSystem fs = FileSystem.get(hiveDumpDir.toUri(), primary.hiveConf);
    assertTrue(fs.exists(ackFile));
    assertTrue(fs.exists(dumpMetaData));
    fs.delete(ackFile, false);
    fs.delete(dumpMetaData, false);
    //delete last five events
    long fifthLastIncEventID = Long.parseLong(incrementalDump1.lastReplicationId) - 4;
    long lastIncEventID = Long.parseLong(incrementalDump1.lastReplicationId);
    assertTrue(lastIncEventID > fifthLastIncEventID);
    for (long eventId = fifthLastIncEventID + 1; eventId <= lastIncEventID; eventId++) {
        Path eventRoot = new Path(hiveDumpDir, String.valueOf(eventId));
        if (fs.exists(eventRoot)) {
            fs.delete(eventRoot, true);
        }
    }
    org.apache.hadoop.hive.ql.parse.repl.dump.Utils.writeOutput(String.valueOf(fifthLastIncEventID), ackLastEventID, primary.hiveConf);
    ReplDumpWork.testDeletePreviousDumpMetaPath(false);
    WarehouseInstance.Tuple incrementalDump2 = primary.run("use " + primaryDbName).dump(primaryDbName);
    assertEquals(incrementalDump1.dumpLocation, incrementalDump2.dumpLocation);
    ackFile = new Path(hiveDumpDir, ReplAck.DUMP_ACKNOWLEDGEMENT.toString());
    assertTrue(fs.exists(ackFile));
    replica.load(replicatedDbName, primaryDbName).run("select * from " + replicatedDbName + ".t1").verifyResults(new String[] { "1", "4" }).run("select * from " + replicatedDbName + ".t3").verifyResults(new String[] { "3" }).runFailure("select * from " + replicatedDbName + ".t2");
}

@Test
public void testCheckPointingDataDumpFailureBootstrapDuringIncremental() throws Throwable {
    List<String> dumpClause = Arrays.asList("'" + HiveConf.ConfVars.HIVE_EXEC_COPYFILE_MAXSIZE.varname + "'='1'", "'" + HiveConf.ConfVars.HIVE_IN_TEST_REPL.varname + "'='false'", "'" + HiveConf.ConfVars.HIVE_EXEC_COPYFILE_MAXNUMFILES.varname + "'='0'", "'" + HiveConf.ConfVars.HIVE_DISTCP_DOAS_USER.varname + "'='" + UserGroupInformation.getCurrentUser().getUserName() + "'");
    WarehouseInstance.Tuple bootstrapDump = primary.run("use " + primaryDbName).run("create table t1(a int) clustered by (a) into 2 buckets" + " stored as orc TBLPROPERTIES ('transactional'='true')").run("insert into t1 values (1)").run("insert into t1 values (2)").dump(primaryDbName, dumpClause);
    replica.load(replicatedDbName, primaryDbName).run("select * from " + replicatedDbName + ".t1").verifyResults(new String[] { "1", "2" });
    dumpClause = Arrays.asList("'" + HiveConf.ConfVars.HIVE_EXEC_COPYFILE_MAXSIZE.varname + "'='1'", "'" + HiveConf.ConfVars.HIVE_IN_TEST_REPL.varname + "'='false'", "'" + HiveConf.ConfVars.HIVE_EXEC_COPYFILE_MAXNUMFILES.varname + "'='0'", "'" + HiveConf.ConfVars.HIVE_DISTCP_DOAS_USER.varname + "'='" + UserGroupInformation.getCurrentUser().getUserName() + "'", "'" + HiveConf.ConfVars.REPL_BOOTSTRAP_ACID_TABLES + "'='true'");
