@Test
public void testIncrementalMetadataReplication() throws Throwable {
    ////////////  Bootstrap   ////////////
    WarehouseInstance.Tuple bootstrapTuple = primary.run("use " + primaryDbName).run("create table table1 (i int, j int)").run("create table table2 (a int, city string) partitioned by (country string)").run("create table table3 (i int, j int)").run("insert into table1 values (1,2)").dump(primaryDbName, Collections.singletonList("'hive.repl.dump.metadata.only'='true'"));
    replica.load(replicatedDbName, primaryDbName).run("use " + replicatedDbName).run("show tables").verifyResults(new String[] { "table1", "table2", "table3" }).run("select * from table1").verifyResults(Collections.emptyList());
    ////////////  First Incremental ////////////
    WarehouseInstance.Tuple incrementalOneTuple = primary.run("use " + primaryDbName).run("alter table table1 rename to renamed_table1").run("insert into table2 partition(country='india') values (1,'mumbai') ").run("create table table4 (i int, j int)").dumpWithCommand("repl dump " + primaryDbName + " with ('hive.repl.dump.metadata.only'='true')");
    replica.load(replicatedDbName, primaryDbName).run("use " + replicatedDbName).run("show tables").verifyResults(new String[] { "renamed_table1", "table2", "table3", "table4" }).run("select * from renamed_table1").verifyResults(Collections.emptyList()).run("select * from table2").verifyResults(Collections.emptyList());
    ////////////  Second Incremental ////////////
    WarehouseInstance.Tuple secondIncremental = primary.run("alter table table2 add columns (zipcode int)").run("alter table table3 change i a string").run("alter table table3 set tblproperties('custom.property'='custom.value')").run("drop table renamed_table1").dumpWithCommand("repl dump " + primaryDbName + " with ('hive.repl.dump.metadata.only'='true')");
    replica.load(replicatedDbName, primaryDbName).run("use " + replicatedDbName).run("show tables").verifyResults(new String[] { "table2", "table3", "table4" }).run("desc table3").verifyResults(new String[] { "a                   \tstring              \t                    ", "j                   \tint                 \t                    " }).run("desc table2").verifyResults(new String[] { "a                   \tint                 \t                    ", "city                \tstring              \t                    ", "country             \tstring              \t                    ", "zipcode             \tint                 \t                    ", "\t \t ", "# Partition Information\t \t ", "# col_name            \tdata_type           \tcomment             ", "country             \tstring              \t                    " }).run("show tblproperties table3('custom.property')").verifyResults(new String[] { "custom.property\tcustom.value" });
}

