    WarehouseInstance.Tuple bootstrapTuple = primary.dump(primaryDbName);
    replica.load(replicatedDbName, primaryDbName).status(replicatedDbName).verifyResult(bootstrapTuple.lastReplicationId);
    WarehouseInstance.Tuple incremental = primary.run("use " + primaryDbName).run("create table table1 (id int) partitioned by (country string)").run("create table table2 (id int)").run("create table table3 (id int) partitioned by (country string)").run("insert into table1 partition(country='india') values(1)").run("insert into table2 values(2)").run("insert into table3 partition(country='india') values(3)").dump(primaryDbName, Collections.emptyList());
    replica.load(replicatedDbName, primaryDbName, Collections.singletonList("'hive.repl.approx.max.load.tasks'='10'")).status(replicatedDbName).verifyResult(incremental.lastReplicationId).run("use " + replicatedDbName).run("select id from table1").verifyResults(new String[] { "1" }).run("select * from table2").verifyResults(new String[] { "2" }).run("select id from table3").verifyResults(new String[] { "3" });
    assert (IncrementalLoadTasksBuilder.getNumIteration() > 1);
    incremental = primary.run("use " + primaryDbName).run("create table  table5 (key int, value int) partitioned by (load_date date) " + "clustered by(key) into 2 buckets stored as orc").run("create table table4 (i int, j int)").run("insert into table4 values (1,2)").dump(primaryDbName, Collections.singletonList("'hive.repl.include.external.tables'='false'"));
    String hiveDumpDir = incremental.dumpLocation + File.separator + ReplUtils.REPL_HIVE_BASE_DIR;
    Path path = new Path(hiveDumpDir);
    FileSystem fs = path.getFileSystem(conf);
    FileStatus[] fileStatus = fs.listStatus(path);
    //for _metadata, _finished_dump and _events_dump
    int numEvents = fileStatus.length - 3;
    replica.load(replicatedDbName, primaryDbName, Arrays.asList("'hive.repl.approx.max.load.tasks'='1','hive.repl.include.external.tables'='false'")).run("use " + replicatedDbName).run("show tables").verifyResults(new String[] { "table1", "table2", "table3", "table4", "table5" }).run("select i from table4").verifyResult("1");
    Assert.assertEquals(IncrementalLoadTasksBuilder.getNumIteration(), numEvents);
}

@Test
public void testIfCkptAndSourceOfReplPropsIgnoredByReplDump() throws Throwable {
    WarehouseInstance.Tuple tuplePrimary = primary.run("use " + primaryDbName).run("create table t1 (place string) partitioned by (country string) " + " tblproperties('custom.property'='custom.value')").run("insert into table t1 partition(country='india') values ('bangalore')").dump(primaryDbName);
    // Bootstrap Repl A -> B
    replica.load(replicatedDbName, primaryDbName).run("repl status " + replicatedDbName).verifyResult(tuplePrimary.lastReplicationId).run("show tblproperties t1('custom.property')").verifyResults(new String[] { "custom.property\tcustom.value" }).dumpFailure(replicatedDbName).run("alter database " + replicatedDbName + " set dbproperties ('" + SOURCE_OF_REPLICATION + "' = '1, 2, 3')").dumpFailure(//can not dump the db before first successful incremental load is done.
    replicatedDbName);
    // do a empty incremental load to allow dump of replicatedDbName
    WarehouseInstance.Tuple temp = primary.dump(primaryDbName, Collections.emptyList());
    // first successful incremental load.
    replica.load(replicatedDbName, primaryDbName);
    // Bootstrap Repl B -> C
    WarehouseInstance.Tuple tupleReplica = replica.run("alter database " + replicatedDbName + " set dbproperties ('" + ReplConst.TARGET_OF_REPLICATION + "' = '')").dump(replicatedDbName);
    String replDbFromReplica = replicatedDbName + "_dupe";
    replica.load(replDbFromReplica, replicatedDbName).run("use " + replDbFromReplica).run("repl status " + replDbFromReplica).verifyResult(tupleReplica.lastReplicationId).run("show tables").verifyResults(new String[] { "t1" }).run("select country from t1").verifyResults(Arrays.asList("india")).run("show tblproperties t1('custom.property')").verifyResults(new String[] { "custom.property\tcustom.value" });
    // Check if DB/table/partition in C doesn't have repl.source.for props. Also ensure, ckpt property
    // is set to bootstrap dump location used in C.
    Database db = replica.getDatabase(replDbFromReplica);
    verifyIfSrcOfReplPropMissing(db.getParameters());
    verifyIfCkptSet(db.getParameters(), tupleReplica.dumpLocation);
    Table t1 = replica.getTable(replDbFromReplica, "t1");
    verifyIfCkptSet(t1.getParameters(), tupleReplica.dumpLocation);
    Partition india = replica.getPartition(replDbFromReplica, "t1", Collections.singletonList("india"));
    verifyIfCkptSet(india.getParameters(), tupleReplica.dumpLocation);
    // Perform alters in A for incremental replication
    WarehouseInstance.Tuple tuplePrimaryInc = primary.run("use " + primaryDbName).run("alter database " + primaryDbName + " set dbproperties('dummy_key'='dummy_val')").run("alter table t1 set tblproperties('dummy_key'='dummy_val')").run("alter table t1 partition(country='india') set fileformat orc").dump(primaryDbName, Collections.emptyList());
    // Incremental Repl A -> B with alters on db/table/partition
    WarehouseInstance.Tuple tupleReplicaInc = replica.load(replicatedDbName, primaryDbName).run("repl status " + replicatedDbName).verifyResult(tuplePrimaryInc.lastReplicationId).run("alter database " + replicatedDbName + " set dbproperties ('" + ReplConst.TARGET_OF_REPLICATION + "' = '')").dump(replicatedDbName, Collections.emptyList());
    // Check if DB in B have ckpt property is set to bootstrap dump location used in B and missing for table/partition.
    db = replica.getDatabase(replicatedDbName);
    verifyIfCkptSet(db.getParameters(), tuplePrimary.dumpLocation);
    t1 = replica.getTable(replicatedDbName, "t1");
    verifyIfCkptPropMissing(t1.getParameters());
    india = replica.getPartition(replicatedDbName, "t1", Collections.singletonList("india"));
    verifyIfCkptPropMissing(india.getParameters());
    // Incremental Repl B -> C with alters on db/table/partition
    replica.load(replDbFromReplica, replicatedDbName).run("use " + replDbFromReplica).run("repl status " + replDbFromReplica).verifyResult(tupleReplicaInc.lastReplicationId).run("show tblproperties t1('custom.property')").verifyResults(new String[] { "custom.property\tcustom.value" });
    // Check if DB/table/partition in C doesn't have repl.source.for props. Also ensure, ckpt property
    // in DB is set to bootstrap dump location used in C but for table/partition, it is missing.
    db = replica.getDatabase(replDbFromReplica);
    verifyIfCkptSet(db.getParameters(), tupleReplica.dumpLocation);
    verifyIfSrcOfReplPropMissing(db.getParameters());
    t1 = replica.getTable(replDbFromReplica, "t1");
    verifyIfCkptPropMissing(t1.getParameters());
    india = replica.getPartition(replDbFromReplica, "t1", Collections.singletonList("india"));
    verifyIfCkptPropMissing(india.getParameters());
    replica.run("drop database if exists " + replDbFromReplica + " cascade");
}

@Test
public void testIfReplTargetSetInIncremental() throws Throwable {
    WarehouseInstance.Tuple tuplePrimary = primary.run("use " + primaryDbName).run("create table t1 (place string) partitioned by (country string)").run("insert into table t1 partition(country='india') values ('bangalore')").dump(primaryDbName);
    // Bootstrap Repl A -> B
    replica.load(replicatedDbName, primaryDbName);
    //Perform empty dump and load
    primary.dump(primaryDbName);
    replica.load(replicatedDbName, primaryDbName);
    assertTrue(MetaStoreUtils.isTargetOfReplication(replica.getDatabase(replicatedDbName)));
    //can not dump db which is target of replication
    replica.dumpFailure(replicatedDbName);
    replica.run("ALTER DATABASE " + replicatedDbName + " Set DBPROPERTIES('repl.target.for' = '')");
    assertFalse(MetaStoreUtils.isTargetOfReplication(replica.getDatabase(replicatedDbName)));
    replica.dump(replicatedDbName);
    // do a empty incremental load to allow dump of replicatedDbName
    primary.run("ALTER DATABASE " + primaryDbName + " Set DBPROPERTIES('custom_property1' = 'custom_value1')").dump(primaryDbName, Collections.emptyList());
    replica.load(replicatedDbName, primaryDbName);
    compareDbProperties(primary.getDatabase(primaryDbName).getParameters(), replica.getDatabase(replicatedDbName).getParameters());
    assertTrue(MetaStoreUtils.isTargetOfReplication(replica.getDatabase(replicatedDbName)));
    //Cannot dump database which is target of replication.
    replica.dumpFailure(replicatedDbName);
}

