    WarehouseInstance.Tuple tuple = primary.run("use " + primaryDbName).run("create external table t2 (place string) partitioned by (country string) row format " + "delimited fields terminated by ',' location '" + externalTableLocation.toString() + "'").run("insert into t2 partition(country='india') values ('bangalore')").dump(primaryDbName, withClause);
