    replica.load(replicatedDbName, primaryDbName, withClause).run("use " + replicatedDbName).run("show tables like 't2'").verifyResults(new String[] { "t2" }).run("select place from t2").verifyResults(new String[] { "bangalore" }).verifyReplTargetProperty(replicatedDbName);
    assertTablePartitionLocation(primaryDbName + ".t2", replicatedDbName + ".t2");
    // add new  data externally, to a partition, but under the table level top directory
    Path partitionDir = new Path(externalTableLocation, "country=india");
    try (FSDataOutputStream outputStream = fs.create(new Path(partitionDir, "file.txt"))) {
        outputStream.write("pune\n".getBytes());
        outputStream.write("mumbai\n".getBytes());
    }
    tuple = primary.run("use " + primaryDbName).run("insert into t2 partition(country='australia') values ('sydney')").dump(primaryDbName, withClause);
    ReplicationTestUtils.assertExternalFileList(Collections.singletonList("t2"), tuple.dumpLocation, primary);
    replica.load(replicatedDbName, primaryDbName, withClause).run("use " + replicatedDbName).run("select distinct(country) from t2").verifyResults(new String[] { "india", "australia" }).run("select place from t2 where country='india'").verifyResults(new String[] { "bangalore", "pune", "mumbai" }).run("select place from t2 where country='australia'").verifyResults(new String[] { "sydney" }).run("show partitions t2").verifyResults(new String[] { "country=australia", "country=india" }).verifyReplTargetProperty(replicatedDbName);
    Path customPartitionLocation = new Path("/" + testName.getMethodName() + "/partition_data/t2/country=france");
    fs.mkdirs(externalTableLocation, new FsPermission("777"));
    // add new partitions to the table, at an external location than the table level directory
    try (FSDataOutputStream outputStream = fs.create(new Path(customPartitionLocation, "file.txt"))) {
        outputStream.write("paris".getBytes());
    }
    primary.run("use " + primaryDbName).run("ALTER TABLE t2 ADD PARTITION (country='france') LOCATION '" + customPartitionLocation.toString() + "'").dump(primaryDbName, withClause);
    replica.load(replicatedDbName, primaryDbName, withClause).run("use " + replicatedDbName).run("select place from t2 where country='france'").verifyResults(new String[] { "paris" }).run("show partitions t2").verifyResults(new String[] { "country=australia", "country=france", "country=india" }).verifyReplTargetProperty(replicatedDbName);
    // change the location of the partition via alter command
    String tmpLocation = "/tmp/" + System.nanoTime();
    primary.miniDFSCluster.getFileSystem().mkdirs(new Path(tmpLocation), new FsPermission("777"));
    primary.run("use " + primaryDbName).run("alter table t2 partition (country='france') set location '" + tmpLocation + "'").dump(primaryDbName, withClause);
    replica.load(replicatedDbName, primaryDbName, withClause).run("use " + replicatedDbName).run("select place from t2 where country='france'").verifyResults(new String[] {}).verifyReplTargetProperty(replicatedDbName);
    // Changing location of one of the partitions shouldn't result in changing location of other
    // partitions as well as that of the table.
    assertTablePartitionLocation(primaryDbName + ".t2", replicatedDbName + ".t2");
    // Changing location of the external table, should result in changes to the location of
    // partition residing within the table location and not the partitions located outside.
    String tmpLocation2 = "/tmp/" + System.nanoTime() + "_2";
    primary.miniDFSCluster.getFileSystem().mkdirs(new Path(tmpLocation2), new FsPermission("777"));
    primary.run("use " + primaryDbName).run("insert into table t2 partition(country='france') values ('lyon')").run("alter table t2 set location '" + tmpLocation2 + "'").dump(primaryDbName, withClause);
    replica.load(replicatedDbName, primaryDbName, withClause);
    assertTablePartitionLocation(primaryDbName + ".t2", replicatedDbName + ".t2");
}

