    primary.run("create database " + extraPrimaryDb + " WITH DBPROPERTIES ( '" + SOURCE_OF_REPLICATION + "' = '1,2,3')");
    WarehouseInstance.Tuple inc2Tuple = primary.run("use " + extraPrimaryDb).run("create table tbl (fld int)").run("use " + primaryDbName).dump(primaryDbName, dumpWithClause);
    Assert.assertEquals(primary.getCurrentNotificationEventId().getEventId(), Long.valueOf(inc2Tuple.lastReplicationId).longValue());
    // Incremental load to existing database with empty dump directory should set the repl id to the last event at src.
    replica.load(replicatedDbName, primaryDbName, loadWithClause).status(replicatedDbName).verifyResult(inc2Tuple.lastReplicationId);
