    replica.load(replicatedDbName, primaryDbName).run("select * From t1").verifyResults(new String[] {}).verifyReplTargetProperty(replicatedDbName);
    for (String path : paths) {
        assertTrue(replica.miniDFSCluster.getFileSystem().exists(new Path(path)));
    }
}

