    // Check if the initial snapshots are created.
    validateInitialSnapshotsCreated(primary.getDatabase(primaryDbName).getLocationUri());
    // Run one more cycle of incremental dump & load to see diff snapshots are created, and add a new table so as to
    // see if it gets included.
    tuple = primary.run("use " + primaryDbName).run("insert into t1 partition(country='india') values ('pune')").run("create external table t2 (place string) partitioned by (country string) row format " + "delimited fields terminated by ',' ").run("insert into t2 partition(country='usa') values ('new york')").dump(primaryDbName);
