    List<String> withClause = ReplicationTestUtils.includeExternalTableClause(true);
    // Create a normal and partitioned table in the database location.
    WarehouseInstance.Tuple tuple = primary.run("use " + primaryDbName).run("alter database " + primaryDbName + " set location '" + externalDatabaseLocation + "'").run("create external table emp1 (id int)").run("insert into emp1 values(1),(2)").run("create external table t2 (place string) partitioned by (country " + "string) row format delimited fields terminated by ','").run("insert into t2 partition(country='india') values ('bangalore')").dump(primaryDbName, withClause);
    // Do a load, post that one snapshot should have been created in the source for each table.
    replica.load(replicatedDbName, primaryDbName, withClause).run("use " + replicatedDbName).run("show tables like 'emp1'").verifyResults(new String[] { "emp1" }).run("select id from emp1").verifyResults(new String[] { "1", "2" }).run("select place from t2").verifyResults(new String[] { "bangalore" }).verifyReplTargetProperty(replicatedDbName);
    // Check the directory is snapshotable.
    assertTrue(fs.getFileStatus(externalDatabaseLocation).isSnapshotEnabled());
    // Check if the snapshot exists at source.
    assertNotNull(fs.getFileStatus(new Path(externalDatabaseLocation, ".snapshot/" + secondSnapshot(primaryDbName.toLowerCase()))));
    // Check if the destination is snapshottable.
    assertTrue(fs.getFileStatus(externalDatabaseLocationDest).isSnapshotEnabled());
    // Check if snapshot exist at destination.
    assertNotNull(fs.getFileStatus(new Path(externalDatabaseLocationDest, ".snapshot/" + firstSnapshot(primaryDbName.toLowerCase()))));
    // Alter database location and create another table inside it.
    tuple = primary.run("use " + primaryDbName).run("alter database " + primaryDbName + " set location '" + externalDatabaseLocationAlter + "'").run("create external table empnew (id int)").run("insert into empnew values (3),(4)").run("drop table emp").run("insert into t2 partition(country='france') " + "values('paris')").dump(primaryDbName, withClause);
