    "insert into t4 partition(country='china') values ('Shanghai')").run(// entry in old existing partition in recreated table.
    "insert into t4 partition(country='nepal') values ('pokhra')").run(// entry for newely added path in list.
    "insert into t1 partition(country='india') values ('chennai')").dump(primaryDbName, withClause);
