    withClause.add("'hive.repl.external.warehouse.single.copy.task.paths'='" + externalTableLocation2.makeQualified(fs.getUri(), fs.getWorkingDirectory()).toString() + "," + externalTableLocation1.makeQualified(fs.getUri(), fs.getWorkingDirectory()).toString() + "'");
