    replica.load(replicatedDbName, primaryDbName, withClause).run("use " + replicatedDbName).run("show tables like 'table1'").verifyResults(new String[] { "table1" }).run("select place from table1 where country='nepal'").verifyResults(new String[] { "kathmandu" }).run("select place from table1 where country='china'").verifyResults(new String[] { "beejing" }).verifyReplTargetProperty(replicatedDbName);
