    replica.load(replicatedDbName, primaryDbName, withClause).run("use " + replicatedDbName).run("select place from table1 where country='china'").verifyResults(new String[] { "beejing", "wuhan" }).verifyReplTargetProperty(replicatedDbName);
    // Verify if diff snapshots is there.
    validateDiffSnapshotsCreated(externalTableLocation1.toString());
