    Path parent = new Path(tuple.dumpLocation).getParent().getParent();
    fs.delete(parent, true);
    // Delete the external data base dir.
    Path dbLocation = new Path(REPLICA_EXTERNAL_BASE, Path.getPathWithoutSchemeAndAuthority(new Path(primary.getDatabase(primaryDbName).getLocationUri())).toString().replaceFirst("/", ""));
    deleteReplRelatedSnapshots(fs, dbLocation, conf);
