public void testRenameTableScenariosBasic() throws Throwable {
    String replPolicy = primaryDbName + ".'in[0-9]+'.'out[0-9]+'";
    String lastReplId = replicateAndVerify(replPolicy, null, null, null, null, new String[] {}, new String[] {});
    String[] originalNonAcidTables = new String[] { "in1", "in2", "out3", "out4", "out5", "out6" };
    createTables(originalNonAcidTables, CreateTableType.NON_ACID);
    // Replicate and verify if only 2 tables are replicated to target.
    String[] replicatedTables = new String[] { "in1", "in2" };
    String[] bootstrapTables = new String[] {};
    lastReplId = replicateAndVerify(replPolicy, replPolicy, lastReplId, null, null, bootstrapTables, replicatedTables);
    // Rename tables to make them satisfy the filter.
    primary.run("use " + primaryDbName).run("alter table out3 rename to in3").run("alter table out4 rename to in4").run("alter table out5 rename to in5");
    replicatedTables = new String[] { "in1", "in2", "in3", "in4", "in5" };
    bootstrapTables = new String[] { "in3", "in4", "in5" };
    lastReplId = replicateAndVerify(replPolicy, replPolicy, lastReplId, null, null, bootstrapTables, replicatedTables);
    primary.run("use " + primaryDbName).run("alter table in3 rename to in7").run(// Double rename, both satisfying the filter, so no bootstrap.
    "alter table in7 rename to in8").run(// out9 does not match the filter so in4 should be dropped.
    "alter table in4 rename to out9").run(// Rename from satisfying name to not satisfying name.
    "alter table in5 rename to out10").run(// from non satisfying to satisfying, should be bootstrapped
    "alter table out10 rename to in11");
    replicatedTables = new String[] { "in1", "in2", "in8", "in11" };
    bootstrapTables = new String[] { "in11" };
    lastReplId = replicateAndVerify(replPolicy, replPolicy, lastReplId, null, null, bootstrapTables, replicatedTables);
    primary.run("use " + primaryDbName).run(// table is renamed from satisfying to satisfying, no bootstrap
    "alter table in8 rename to in12").run(// out9 does not match the filter so in13 should be bootstrapped.
    "alter table out9 rename to in13").run(// table is renamed from satisfying to satisfying
    "alter table in13 rename to in14").run(// this will change the rename to drop in2
    "alter table in2 rename to out200").run(// this will add the bootstrap for in200
    "alter table out200 rename to in200").run(// this will change the rename to drop
    "alter table in1 rename to out100").run(// this will add the bootstrap
    "alter table out100 rename to in100").run(// table in100 is dropped, so no bootstrap should happen.
    "drop table in100");
    replicatedTables = new String[] { "in200", "in12", "in11", "in14" };
    bootstrapTables = new String[] { "in14", "in200" };
    replicateAndVerify(replPolicy, replPolicy, lastReplId, null, null, bootstrapTables, replicatedTables);
}

