    msClient.abortTxns(Lists.newArrayList(openTxnId));
    // Compact 4 and 5.
    runMajorCompaction(dbName, tblName);
    verifyFooBarResult(tblName, 2);
    verifyHasBase(table.getSd(), fs, "base_0000005_v0000016");
