        }
    }
    assertTrue("Found temp table", foundTable);
    // Test getTables() with no table name pattern
    rs = md.getTables(null, null, null, null);
    foundTable = false;
    while (rs.next()) {
        String tableName = rs.getString(3);
        if (tableName.equalsIgnoreCase(tempTableName)) {
