@Test
public void testDone() throws Exception {
    try (CuratorFramework client = getClient()) {
        client.start();
        client.create().creatingParentContainersIfNeeded().forPath(BARRIER_ROOT_PATH);
        final KillQueryZookeeperManager.KillQueryZookeeperBarrier barrier = new KillQueryZookeeperManager.KillQueryZookeeperBarrier(client, BARRIER_ROOT_PATH);
