@Test
public void testMetastoreProxyUser() throws Exception {
    setup();
    final String proxyUserName = "proxyUser";
    //set the configuration up such that proxyUser can act on
    //behalf of all users belonging to the group foo_bar_group (
    //a dummy group)
    String[] groupNames = new String[] { "foo_bar_group" };
    setGroupsInConf(groupNames, proxyUserName);
    final UserGroupInformation delegationTokenUser = UserGroupInformation.getCurrentUser();
    final UserGroupInformation proxyUserUgi = UserGroupInformation.createRemoteUser(proxyUserName);
    String tokenStrForm = proxyUserUgi.doAs(new PrivilegedExceptionAction<String>() {

        public String run() throws Exception {
            try {
                //Since the user running the test won't belong to a non-existent group
                //foo_bar_group, the call to getDelegationTokenStr will fail
                return getDelegationTokenStr(delegationTokenUser, proxyUserUgi);
            } catch (AuthorizationException ae) {
                return null;
            }
        }
    });
    Assert.assertTrue("Expected the getDelegationToken call to fail", tokenStrForm == null);
    //set the configuration up such that proxyUser can act on
    //behalf of all users belonging to the real group(s) that the
    //user running the test belongs to
    setGroupsInConf(UserGroupInformation.getCurrentUser().getGroupNames(), proxyUserName);
    tokenStrForm = proxyUserUgi.doAs(new PrivilegedExceptionAction<String>() {

        public String run() throws Exception {
            try {
                //Since the user running the test belongs to the group
                //obtained above the call to getDelegationTokenStr will succeed
                return getDelegationTokenStr(delegationTokenUser, proxyUserUgi);
            } catch (AuthorizationException ae) {
                return null;
            }
        }
    });
    Assert.assertTrue("Expected the getDelegationToken call to not fail", tokenStrForm != null);
    Token<DelegationTokenIdentifier> t = new Token<DelegationTokenIdentifier>();
    t.decodeFromUrlString(tokenStrForm);
    //check whether the username in the token is what we expect
    DelegationTokenIdentifier d = new DelegationTokenIdentifier();
    d.readFields(new DataInputStream(new ByteArrayInputStream(t.getIdentifier())));
    Assert.assertTrue("Usernames don't match", delegationTokenUser.getShortUserName().equals(d.getUser().getShortUserName()));
}

@Test
public void testPassword() throws Exception {
    if (!doesHadoopPasswordAPIExist()) {
        System.out.println("Skipping Password API test" + " because this version of hadoop-2 does not support the password API.");
        return;
    }
    String credName = "my.password";
    String credName2 = "my.password2";
    String credName3 = "my.password3";
    String hiveConfPassword = "conf value";
    String credPassword = "cred value";
    String confOnlyPassword = "abcdefg";
    String credOnlyPassword = "12345";
    // Set up conf
    Configuration conf = new Configuration();
    // Will be superceded by credential provider
    conf.set(credName, hiveConfPassword);
    // Will not be superceded
    conf.set(credName2, confOnlyPassword);
    assertEquals(hiveConfPassword, conf.get(credName));
    assertEquals(confOnlyPassword, conf.get(credName2));
    assertNull("credName3 should not exist in HiveConf", conf.get(credName3));
    // Configure getPassword() to fall back to conf if credential doesn't have entry
    conf.set("hadoop.security.credential.clear-text-fallback", "true");
    // Set up CredentialProvider
    conf.set("hadoop.security.credential.provider.path", "jceks://file/" + tmpDir.toURI().getPath() + "/test.jks");
    // CredentialProvider/CredentialProviderFactory may not exist, depending on the version of
    // hadoop-2 being used to build Hive. Use reflection to do the following lines
    // to allow the test to compile regardless of what version of hadoop-2.
    // Update credName entry in the credential provider.
    //CredentialProvider provider = CredentialProviderFactory.getProviders(conf).get(0);
    //provider.createCredentialEntry(credName, credPassword.toCharArray());
    //provider.createCredentialEntry(credName3, credOnlyPassword.toCharArray());
    //provider.flush();
    Class credentialProviderClass = Class.forName("org.apache.hadoop.security.alias.CredentialProvider");
    Class credentialProviderFactoryClass = Class.forName("org.apache.hadoop.security.alias.CredentialProviderFactory");
    Object provider = ((List) invoke(credentialProviderFactoryClass, null, "getProviders", conf)).get(0);
    invoke(credentialProviderClass, provider, "createCredentialEntry", credName, credPassword.toCharArray());
    invoke(credentialProviderClass, provider, "createCredentialEntry", credName3, credOnlyPassword.toCharArray());
    invoke(credentialProviderClass, provider, "flush");
    // If credential provider has entry for our credential, then it should be used
    assertEquals("getPassword() should use match value in credential provider", credPassword, ShimLoader.getHadoopShims().getPassword(conf, credName));
    // If cred provider doesn't have entry, fall back to conf
    assertEquals("getPassword() should match value from conf", confOnlyPassword, ShimLoader.getHadoopShims().getPassword(conf, credName2));
    // If cred provider has entry and conf does not, cred provider is used.
    // This is our use case of not having passwords stored in in the clear in hive conf files.
    assertEquals("getPassword() should use credential provider if conf has no value", credOnlyPassword, ShimLoader.getHadoopShims().getPassword(conf, credName3));
    // If neither cred provider or conf have entry, return null;
    assertNull("null if neither cred provider or conf have entry", ShimLoader.getHadoopShims().getPassword(conf, "nonexistentkey"));
}

