@Test
public void testRecordReader() {
    List<KafkaWritable> serRecords = expectedRecords.stream().map((consumerRecord) -> new KafkaWritable(consumerRecord.partition(), consumerRecord.offset(), consumerRecord.timestamp(), consumerRecord.value(), consumerRecord.key())).collect(Collectors.toList());
    KafkaRecordReader recordReader = new KafkaRecordReader();
    TaskAttemptContext context = new TaskAttemptContextImpl(this.conf, new TaskAttemptID());
    recordReader.initialize(new KafkaInputSplit(currentTopic, 0, 50L, 100L, null), context);
    for (int i = 50; i < 100; ++i) {
        KafkaWritable record = new KafkaWritable();
        Assert.assertTrue(recordReader.next(null, record));
        Assert.assertEquals(serRecords.get(i), record);
    }
    recordReader.close();
}

@Test(expected = KafkaRecordIterator.PollTimeoutException.class)
public void testPullingBeyondLimit() {
    //FYI In the Tx world Commits can introduce offset gaps therefore
    //thus(RECORD_NUMBER + 1) as beyond limit offset is only true if the topic has not Tx or any Control msg.
    long increment = readUncommitted ? 1 : 2;
    long requestedEnd = expectedRecords.size() + increment;
    long requestedStart = expectedRecords.size() - 1;
    this.kafkaRecordIterator = new KafkaRecordIterator(this.consumer, topicPartition, requestedStart, requestedEnd, POLL_TIMEOUT_MS);
    this.compareIterator(expectedRecords.stream().filter((consumerRecord) -> consumerRecord.offset() >= requestedStart).collect(Collectors.toList()), this.kafkaRecordIterator);
}

