@Test
public void computeOptimizedScanPartitionBinaryOpFilter() {
    KafkaScanTrimmer kafkaScanTrimmer = new KafkaScanTrimmer(fullHouse, null);
    int partitionId = 2;
    ExprNodeDesc constant = ConstantExprBuilder.build(partitionId);
    final List<ExprNodeDesc> children = Lists.newArrayList(partitionColumn, constant);
    ExprNodeGenericFuncDesc node = eq(children);
    assertNotNull(node);
    Map actual = kafkaScanTrimmer.computeOptimizedScan(SerializationUtilities.deserializeExpression(SerializationUtilities.serializeExpression(node)));
    Map expected = Maps.filterValues(fullHouse, tp -> Objects.requireNonNull(tp).getPartition() == partitionId);
    Assert.assertEquals(expected, actual);
    ExprNodeGenericFuncDesc lessNode = lessThan(children);
    assertNotNull(lessNode);
    actual = kafkaScanTrimmer.computeOptimizedScan(SerializationUtilities.deserializeExpression(SerializationUtilities.serializeExpression(lessNode)));
    expected = Maps.filterValues(fullHouse, tp -> Objects.requireNonNull(tp).getPartition() < partitionId);
    Assert.assertEquals(expected, actual);
    ExprNodeGenericFuncDesc lessEqNode = lessThanEq(children);
    assertNotNull(lessEqNode);
    actual = kafkaScanTrimmer.computeOptimizedScan(SerializationUtilities.deserializeExpression(SerializationUtilities.serializeExpression(lessEqNode)));
    expected = Maps.filterValues(fullHouse, tp -> Objects.requireNonNull(tp).getPartition() <= partitionId);
    Assert.assertEquals(expected, actual);
}

@Test
public void computeOptimizedScanFalseFilter() {
    KafkaScanTrimmer kafkaScanTrimmer = new KafkaScanTrimmer(fullHouse, null);
    ExprNodeGenericFuncDesc falseFilter = and(Lists.newArrayList(eq(Lists.newArrayList(partitionColumn, zeroInt)), eq(Lists.newArrayList(partitionColumn, threeInt))));
    assertNotNull(falseFilter);
    Map actual = kafkaScanTrimmer.computeOptimizedScan(SerializationUtilities.deserializeExpression(SerializationUtilities.serializeExpression(falseFilter)));
    Assert.assertTrue(actual.isEmpty());
    ExprNodeGenericFuncDesc falseFilter2 = and(Lists.newArrayList(eq(Lists.newArrayList(offsetColumn, thirtyFiveLong)), eq(Lists.newArrayList(offsetColumn, fortyLong))));
    assertNotNull(falseFilter2);
    actual = kafkaScanTrimmer.computeOptimizedScan(SerializationUtilities.deserializeExpression(SerializationUtilities.serializeExpression(falseFilter2)));
    Assert.assertTrue(actual.isEmpty());
    ExprNodeGenericFuncDesc filter3 = or(Lists.newArrayList(falseFilter, falseFilter2));
    assertNotNull(filter3);
    actual = kafkaScanTrimmer.computeOptimizedScan(SerializationUtilities.deserializeExpression(SerializationUtilities.serializeExpression(filter3)));
    Assert.assertTrue(actual.isEmpty());
    ExprNodeGenericFuncDesc filter4 = and(Lists.newArrayList(filter3, eq(Lists.newArrayList(partitionColumn, zeroInt))));
    assertNotNull(filter4);
    actual = kafkaScanTrimmer.computeOptimizedScan(SerializationUtilities.deserializeExpression(SerializationUtilities.serializeExpression(filter4)));
    Assert.assertTrue(actual.isEmpty());
}

@Test
public void computeOptimizedScanOrAndCombinedFilter() {
    KafkaScanTrimmer kafkaScanTrimmer = new KafkaScanTrimmer(fullHouse, null);
    // partition = 0 and 30 <= offset < 35 or partition = 3 and 35 <= offset < 75  or (partition = 0 and offset = 40)
    ExprNodeGenericFuncDesc part1 = and(Lists.newArrayList(greaterThanEq(Lists.newArrayList(offsetColumn, thirtyLong)), eq(Lists.newArrayList(partitionColumn, zeroInt)), lessThan(Lists.newArrayList(offsetColumn, thirtyFiveLong))));
    ExprNodeGenericFuncDesc part2 = and(Lists.newArrayList(greaterThanEq(Lists.newArrayList(offsetColumn, thirtyFiveLong)), eq(Lists.newArrayList(partitionColumn, threeInt)), lessThan(Lists.newArrayList(offsetColumn, seventyFiveLong))));
    ExprNodeGenericFuncDesc part3 = and(Lists.newArrayList(eq(Lists.newArrayList(offsetColumn, fortyLong)), eq(Lists.newArrayList(partitionColumn, zeroInt))));
    ExprNodeGenericFuncDesc orExpression = or(Lists.newArrayList(part1, part2, part3));
    assertNotNull(orExpression);
    Map actual = kafkaScanTrimmer.computeOptimizedScan(SerializationUtilities.deserializeExpression(SerializationUtilities.serializeExpression(orExpression)));
    TopicPartition tpZero = new TopicPartition(topic, 0);
    TopicPartition toThree = new TopicPartition(topic, 3);
    KafkaInputSplit split1 = new KafkaInputSplit(topic, 0, 30, 41, PATH);
    KafkaInputSplit split2 = new KafkaInputSplit(topic, 3, 35, 75, PATH);
    Map expected = ImmutableMap.of(tpZero, split1, toThree, split2);
    Assert.assertEquals(expected, actual);
}

@Test
public void computeOptimizedScanPartitionOrAndCombinedFilter() {
    KafkaScanTrimmer kafkaScanTrimmer = new KafkaScanTrimmer(fullHouse, null);
    // partition = 1 or (partition >2 and <= 3)
    ExprNodeGenericFuncDesc eq = eq(Lists.newArrayList(partitionColumn, ConstantExprBuilder.build(1)));
    ExprNodeGenericFuncDesc lessEq = lessThanEq(Lists.newArrayList(partitionColumn, ConstantExprBuilder.build(3)));
    ExprNodeGenericFuncDesc greater = greaterThan(Lists.newArrayList(partitionColumn, ConstantExprBuilder.build(2)));
    ExprNodeGenericFuncDesc orNode = or(Lists.newArrayList(and(Lists.newArrayList(lessEq, greater)), eq));
    Map actual = kafkaScanTrimmer.computeOptimizedScan(SerializationUtilities.deserializeExpression(SerializationUtilities.serializeExpression(orNode)));
    Map expected = Maps.filterValues(fullHouse, tp -> Objects.requireNonNull(tp).getPartition() == 1 || tp.getPartition() == 3);
    Assert.assertEquals(expected, actual);
    assertNotNull(orNode);
}

