    Assert.assertEquals(jobProperties.get(KafkaTableProperties.HIVE_KAFKA_BOOTSTRAP_SERVERS.getName()), LOCALHOST_9291);
    Assert.assertEquals(KafkaOutputFormat.WriteSemantic.EXACTLY_ONCE.name(), jobProperties.get(KafkaTableProperties.WRITE_SEMANTIC_PROPERTY.getName()));
    Assert.assertEquals(jobProperties.get(KafkaUtils.CONSUMER_CONFIGURATION_PREFIX + "." + ConsumerConfig.ISOLATION_LEVEL_CONFIG), "read_committed");
    Assert.assertEquals(KafkaOutputFormat.WriteSemantic.EXACTLY_ONCE.name(), jobProperties.get(KafkaTableProperties.WRITE_SEMANTIC_PROPERTY.getName()));
