@Test
public void testMetadataEnumLookupMapper() {
    int partition = 1;
    long offset = 5L;
    long ts = 1000000L;
    byte[] value = "value".getBytes();
    byte[] key = "key".getBytes();
    // ORDER MATTERS here.
    List<Writable> expectedWritables = Arrays.asList(new BytesWritable(key), new IntWritable(partition), new LongWritable(offset), new LongWritable(ts));
