}

@Test
public void testAbruptlyClosedOutput() throws Exception {
    List<byte[]> values = Arrays.asList(new byte[] { (byte) 1 }, new byte[] { (byte) 2 }, RandomTypeUtil.getRandString(rand, alphabet, 99).getBytes(), RandomTypeUtil.getRandString(rand, alphabet, 1024).getBytes());
    // Close the PipedOutputStream before we close the outermost OutputStream.
    // Try non-chunked stream. There should be no issues assuming we flushed the streams before closing.
    TestStreams nonChunkedStreams = new TestStreams(false);
    nonChunkedStreams.values = values;
    BasicUsageWriter writer1 = new BasicUsageWriter(nonChunkedStreams, true, true);
    BasicUsageReader reader1 = new BasicUsageReader(nonChunkedStreams);
    runTest(writer1, reader1, nonChunkedStreams);
    assertTrue(reader1.allValuesRead);
    assertNull(writer1.getError());
    assertNull(reader1.getError());
    // Try with chunked stream. Here the chunked output didn't get a chance to write the end-of-data
    // indicator, so the chunked input does not know to stop reading.
    TestStreams chunkedStreams = new TestStreams(true);
    chunkedStreams.values = values;
    BasicUsageWriter writer2 = new BasicUsageWriter(chunkedStreams, true, true);
    BasicUsageReader reader2 = new BasicUsageReader(chunkedStreams);
    runTest(writer2, reader2, chunkedStreams);
    assertTrue(reader2.allValuesRead);
    assertFalse(((ChunkedInputStream) chunkedStreams.in).isEndOfData());
    // Closing the chunked output stream early gives an error
    assertNotNull(writer2.getError());
    // In this case we should expect the test to have failed at the very last read() check.
    assertNotNull(reader2.getError());
}

/**
 * Runs a simple test where a thread is running in a loop, getting read locks w/o having to
 * deal with any contention. The test shows that the locks are received rather quick and tha
 * all metrics for write locks remain zero.
 */
@Ignore("Test requires available CPU resources for background threads")
@Test
public void testWithoutContention() throws Exception {
    final long execTime = 100;
    MetricsSource ms = ReadWriteLockMetrics.createLockMetricsSource("test1");
    ReadWriteLock rwl = create(new ReentrantReadWriteLock(), ms);
    LockHolder lhR = new LockHolder(rwl.readLock(), execTime);
    // wait for the thread to do its locks and waits (for 100ms)
    lhR.join();
    // get the reported metrics
    MockMetricsCollector tmc = new MockMetricsCollector();
    ms.getMetrics(tmc, true);
    List<MockMetricsCollector.MockRecord> result = tmc.getRecords();
    assertEquals("Unexpected amount of metrics", 1, result.size());
    MockMetricsCollector.MockRecord rec = result.get(0);
    // verify label and context (context is hard coded)
    assertEquals("Invalid record label", "test1", rec.getLabel());
    assertEquals("Invalid record context", "Locking", rec.getContext());
    // we expect around exectome / thread loop time executions
    assertWithTolerance("Unexpected count of lock executions (reader)", execTime / LockHolder.LOCK_HOLD_TIME, lhR.getLockCount());
    assertEquals("Counting the locks failed", lhR.getLockCount(), rec.getMetrics().get(ReadLockCount));
    // sanity check in read lock metrics
    assertNotEquals("Local thread should have lock time", lhR.getLockSum(), 0);
    assertNotEquals("Accounted lock time zero", rec.getMetrics().get(ReadLockWaitTimeTotal), 0);
    assertTrue("Local measurement larger (overhead)", rec.getMetrics().get(ReadLockWaitTimeTotal).longValue() < lhR.getLockSum());
    assertNotEquals("Local thread should have max lock time", lhR.getLockMax(), 0);
    assertNotEquals("Accounted lock max time zero", rec.getMetrics().get(ReadLockWaitTimeMax), 0);
    assertTrue("Local max larger (overhead)", rec.getMetrics().get(ReadLockWaitTimeMax).longValue() < lhR.getLockMax());
    assertTrue("Max greater or equal to avergae lock time", (rec.getMetrics().get(ReadLockWaitTimeTotal).longValue() / rec.getMetrics().get(ReadLockCount).longValue()) <= rec.getMetrics().get(ReadLockWaitTimeMax).longValue());
    assertTrue("Lock time less than 1% (no contention)", rec.getMetrics().get(ReadLockWaitTimeTotal).longValue() < toNano(execTime / 100L));
    // sanity check on write lock metrics (should be all zero)
    assertEquals("No writer lock activity expected (total)", rec.getMetrics().get(WriteLockWaitTimeTotal), 0L);
    assertEquals("No writer lock activity expected (max)", rec.getMetrics().get(WriteLockWaitTimeMax), 0L);
    assertEquals("No writer lock activity expected (count)", rec.getMetrics().get(WriteLockCount), 0L);
}

/**
 * Test where read/write lock contention is tested.
 * This test has a background thread that tries to get read locks within a
 * loop while the main thread holds a write lock for half of the tex
 * execution time. The test verifies that the reported metric for read lock
 * wait time reflects that the thread was blocked until the write lock was
 * released. It also performs basic sanity checks on the read and write lock
 * metrics.
 */
@Ignore("Test requires available CPU resources for background threads")
@Test
public void testWithContention() throws Exception {
    final long execTime = 200;
    MetricsSource ms = ReadWriteLockMetrics.createLockMetricsSource("test1");
    ReadWriteLock rwl = create(new ReentrantReadWriteLock(), ms);
    LockHolder lhR = new LockHolder(rwl.readLock(), execTime);
    // get a write lock for half of the execution time
    try {
        long endOfLock = nanoTime() + toNano(execTime / 2);
        rwl.writeLock().lock();
        while (nanoTime() < endOfLock) {
            // spin until end time is reached
        }
    } finally {
        rwl.writeLock().unlock();
    }
    // wait for the thread to do its locks and waits (for 100ms)
    lhR.join();
    MockMetricsCollector tmc = new MockMetricsCollector();
    ms.getMetrics(tmc, true);
    List<MockMetricsCollector.MockRecord> result = tmc.getRecords();
    assertEquals("Unexpected amount of metrics", 1, result.size());
    MockMetricsCollector.MockRecord rec = result.get(0);
    // sanity checks for read lock values
    assertEquals("Verifying the loop count (read lock)", lhR.getLockCount(), rec.getMetrics().get(ReadLockCount).longValue());
    assertWithTolerance("Only half of possible read locks expected", (execTime / LockHolder.LOCK_HOLD_TIME) / 2, rec.getMetrics().get(ReadLockCount).longValue());
    assertWithTolerance("Max read lock wait time close to write lock hold", toNano(execTime / 2), rec.getMetrics().get(ReadLockWaitTimeMax).longValue());
    assertTrue("Total read lock wait time larger than max", rec.getMetrics().get(ReadLockWaitTimeMax).longValue() < rec.getMetrics().get(ReadLockWaitTimeTotal).longValue());
    // sanity check for write locks
    assertEquals("Write lock count supposed to be one", 1, rec.getMetrics().get(WriteLockCount).longValue());
    assertTrue("Write lock wait time non zero", 0L < rec.getMetrics().get(WriteLockWaitTimeTotal).longValue());
    assertEquals("With one lock, total should me max", rec.getMetrics().get(WriteLockWaitTimeTotal), rec.getMetrics().get(WriteLockWaitTimeMax));
}

/**
 * Testing the <code>wrap</code> function for different configuration
 * combinations.
 */
@Test
public void testWrap() throws Exception {
    Configuration testConf = new Configuration();
    MetricsSource ms = ReadWriteLockMetrics.createLockMetricsSource("testConf");
    // default = passthrough
    ReadWriteLock rwlDef = ReadWriteLockMetrics.wrap(testConf, new ReentrantReadWriteLock(), ms);
    assertTrue("Basic ReentrantReadWriteLock expected", rwlDef instanceof ReentrantReadWriteLock);
    assertFalse("Basic ReentrantReadWriteLock expected", rwlDef instanceof ReadWriteLockMetrics);
    // false = pass through
    HiveConf.setBoolVar(testConf, HiveConf.ConfVars.LLAP_COLLECT_LOCK_METRICS, false);
    ReadWriteLock rwlBasic = ReadWriteLockMetrics.wrap(testConf, new ReentrantReadWriteLock(), ms);
    assertTrue("Basic ReentrantReadWriteLock expected", rwlBasic instanceof ReentrantReadWriteLock);
    assertFalse("Basic ReentrantReadWriteLock expected", rwlBasic instanceof ReadWriteLockMetrics);
    // true = wrap
    HiveConf.setBoolVar(testConf, HiveConf.ConfVars.LLAP_COLLECT_LOCK_METRICS, true);
    ReadWriteLock rwlWrap = ReadWriteLockMetrics.wrap(testConf, new ReentrantReadWriteLock(), ms);
    assertTrue("Wrapped lock expected", rwlWrap instanceof ReadWriteLockMetrics);
    // null = passthrough
    ReadWriteLock rwlNoConf = ReadWriteLockMetrics.wrap(null, new ReentrantReadWriteLock(), null);
    assertTrue("Basic ReentrantReadWriteLock expected", rwlNoConf instanceof ReentrantReadWriteLock);
    assertFalse("Basic ReentrantReadWriteLock expected", rwlNoConf instanceof ReadWriteLockMetrics);
}

@Test
public void testUsage() {
    Schema schema = createTestSchema();
    Row row = new Row(schema);
    Random rand = new Random();
    int iterations = 100;
    for (int idx = 0; idx < iterations; ++idx) {
        // Set the row values
        boolean isNullCol0 = (rand.nextDouble() <= 0.25);
        String col0 = RandomStringUtils.random(10);
        row.setValue(0, isNullCol0 ? null : col0);
        boolean isNullCol1 = (rand.nextDouble() <= 0.25);
        Integer col1 = Integer.valueOf(rand.nextInt());
        row.setValue(1, isNullCol1 ? null : col1);
        // Validate the row values
        if (isNullCol0) {
            assertTrue(row.getValue(0) == null);
            assertTrue(row.getValue("col0") == null);
        } else {
            assertTrue(row.getValue(0) != null);
            assertEquals(col0, row.getValue(0));
            assertEquals(col0, row.getValue("col0"));
        }
        if (isNullCol1) {
            assertTrue(row.getValue(1) == null);
            assertTrue(row.getValue("col1") == null);
        } else {
            assertTrue(row.getValue(1) != null);
            assertEquals(col1, row.getValue(1));
            assertEquals(col1, row.getValue("col1"));
        }
    }
}

