    int fragNum = 1;
    int attemptNum = 0;
    SubmitWorkRequestProto sRequest1 = LlapDaemonTestUtils.buildSubmitProtoRequest(fragNum, attemptNum, appId, dagId, vId, "dagName", 0, 0, 0, 0, 1, credentials);
