 *      conf.setVar(HiveConf.ConfVars.METASTOREPWD, "hive");
 *      conf.setVar(HiveConf.ConfVars.METASTORE_CONNECTION_DRIVER, "com.mysql.jdbc.Driver");
 * 3. Remove TxnDbUtil.prepDb(); in TxnHandler.checkQFileTestHack()
