    Assert.assertEquals(String.format("Unexpected batch size in retry attempt %d ", retryAttempt++), 5, apds.get(0).size());
    Assert.assertEquals(String.format("Unexpected batch size in retry attempt %d ", retryAttempt++), 5, apds.get(1).size());
    assertTrue(ifNotExistsArg.getValue());
    assertFalse(needResultsArg.getValue());
}

