@Test
public void test() throws Throwable {
    byte[][] sampled;
    sampled = new byte[][] { tmp100, tmp100, tmp100, tmp100, tmp100, tmp100, tmp100, tmp100, tmp100, tmp100 };
    // 3
    assertKeys(sampled, tmp100);
