    random = new Random(30000);
    // Start with capacity 1; make sure we expand on every put.
    VectorMapJoinFastLongHashMultiSet map = new VectorMapJoinFastLongHashMultiSet(false, false, HashTableKeyType.LONG, 1, 0.0000001f, WB_SIZE, -1, tableDesc);
    VerifyFastLongHashMultiSet verifyTable = new VerifyFastLongHashMultiSet();
    for (int i = 0; i < 6; ++i) {
        long key;
        while (true) {
            key = random.nextLong();
            if (!verifyTable.contains(key)) {
                // Unique keys for this test.
                break;
            }
        }
        map.testPutRow(key);
        verifyTable.add(key);
        // verifyTable.verify(map);
    }
    verifyTable.verify(map);
    // assertEquals(1 << 18, map.getCapacity());
}

