    TimestampColumnVector timestampColVector = new TimestampColumnVector();
    Timestamp[] randTimestamps = new Timestamp[VectorizedRowBatch.DEFAULT_SIZE];
    for (int i = 0; i < VectorizedRowBatch.DEFAULT_SIZE; i++) {
