@Test
public void testBorrowSelected() {
    MutableFilterContext mutableFilterContext = new VectorizedRowBatch(0);
    mutableFilterContext.setFilterContext(true, new int[] { 100, 200 }, 2);
    int[] borrowedSelected = mutableFilterContext.updateSelected(1);
    // make sure we borrowed the existing array
    Assert.assertEquals(2, borrowedSelected.length);
    Assert.assertEquals(100, borrowedSelected[0]);
    Assert.assertEquals(200, borrowedSelected[1]);
    borrowedSelected = mutableFilterContext.updateSelected(3);
    Assert.assertEquals(3, borrowedSelected.length);
    Assert.assertEquals(0, borrowedSelected[0]);
    Assert.assertEquals(0, borrowedSelected[1]);
    Assert.assertEquals(0, borrowedSelected[2]);
}

@Test
public void testFileSystemIsNotInitializedWithKnownTail() throws IOException {
    JobConf conf = new JobConf();
    Path path = new Path("fmock:///testtable/bucket_0");
    conf.set("hive.orc.splits.include.file.footer", "true");
    conf.set("fs.defaultFS", "fmock:///");
    conf.set("fs.mock.impl", FailingMockFileSystem.class.getName());
    OrcProto.FileTail tail = OrcProto.FileTail.newBuilder().setFooter(Footer.newBuilder().addTypes(OrcProto.Type.newBuilder().setKind(OrcProto.Type.Kind.BINARY).build()).build()).build();
    OrcFile.ReaderOptions readerOptions = EncodedOrcFile.readerOptions(conf).filesystem(() -> {
        throw new RuntimeException("Filesystem should not have been initialized");
    }).orcTail(new OrcTail(tail, new BufferChunk(0, 0), -1));
    // an orc reader is created, this should not cause filesystem initialization
    // because orc tail is already provided and we are not making any real reads.
    Reader reader = EncodedOrcFile.createReader(path, readerOptions);
    // Following initiates the creation of data reader in ORC reader. This should
    // not cause file system initialization either as we are still not making any
    // real read.
    reader.rows();
}

@Test
public void testReadLength() throws IOException {
    ByteBuffer one = ByteBuffer.wrap(new byte[] { 1 }), two = ByteBuffer.wrap(new byte[] { 2 }), three = ByteBuffer.wrap(new byte[] { 3 }), twoThree = ByteBuffer.wrap(new byte[] { 2, 3 }), oneTwo = ByteBuffer.wrap(new byte[] { 1, 2 });
    BufferChunk bc = new BufferChunk(one, 0);
    int[] result = new int[3];
    List<IncompleteCb> l = new ArrayList<>();
    IoTrace trace = new IoTrace(0, false);
    BufferChunk rv = EncodedReaderImpl.readLengthBytesFromSmallBuffers(bc, 0l, result, l, true, trace);
    assertNull(rv);
    one.position(0);
    bc.insertAfter(new BufferChunk(two, 1));
    Arrays.fill(result, -1);
    rv = EncodedReaderImpl.readLengthBytesFromSmallBuffers(bc, 0l, result, l, true, trace);
    assertNull(rv);
    one.position(0);
    two.position(0);
    bc.insertAfter(new BufferChunk(two, 1)).insertAfter(new BufferChunk(three, 2));
    Arrays.fill(result, -1);
    rv = EncodedReaderImpl.readLengthBytesFromSmallBuffers(bc, 0l, result, l, true, trace);
    assertNotNull(rv);
    for (int i = 0; i < result.length; ++i) {
        assertEquals(i + 1, result[i]);
    }
    one.position(0);
    bc.insertAfter(new BufferChunk(twoThree, 1));
    Arrays.fill(result, -1);
    rv = EncodedReaderImpl.readLengthBytesFromSmallBuffers(bc, 0l, result, l, true, trace);
    assertNotNull(rv);
    for (int i = 0; i < result.length; ++i) {
        assertEquals(i + 1, result[i]);
    }
    bc = new BufferChunk(oneTwo, 0);
    Arrays.fill(result, -1);
    rv = EncodedReaderImpl.readLengthBytesFromSmallBuffers(bc, 0l, result, l, true, trace);
    assertNull(rv);
    three.position(0);
    bc.insertAfter(new BufferChunk(three, 2));
    Arrays.fill(result, -1);
    rv = EncodedReaderImpl.readLengthBytesFromSmallBuffers(bc, 0l, result, l, true, trace);
    assertNotNull(rv);
    for (int i = 0; i < result.length; ++i) {
        assertEquals(i + 1, result[i]);
    }
}

@Test
public void testValidKeyIndex() throws Exception {
    // Try with 0 row file.
    createTestAcidFile(testFilePath, 0, new GoodKeyIndexBuilder());
    checkValidKeyIndex(testFilePath);
    // Attempting to fix a valid - should not result in a new file.
    fixValidIndex(testFilePath);
    // Try single stripe
    createTestAcidFile(testFilePath, 100, new GoodKeyIndexBuilder());
    checkValidKeyIndex(testFilePath);
    // Attempting to fix a valid - should not result in a new file.
    fixValidIndex(testFilePath);
    // Multiple stripes
    createTestAcidFile(testFilePath, 12000, new GoodKeyIndexBuilder());
    checkValidKeyIndex(testFilePath);
    // Attempting to fix a valid - should not result in a new file.
    fixValidIndex(testFilePath);
}

