            minInt = x;
        }
        if (i == 0 || x > maxInt) {
            maxInt = x;
        }
        if (i == 0 || y.compareTo(minStr) < 0) {
            minStr = y;
        }
        if (i == 0 || y.compareTo(maxStr) > 0) {
            maxStr = y;
        }
        writer.addRow(inner(x, y));
    }
    writer.close();
