@Test
public void testBucketIdRollOver() {
    for (int i = 0; i < 16384; i++) {
        int encode = BucketCodec.getCodec(1).encode(new AcidOutputFormat.Options(null).bucket(i).statementId(10).maxStmtId(// 2 bit free
        0b001000000000));
        assertEquals(i % 4096, BucketCodec.getCodec(1).decodeWriterId(encode));
        if (i < 4096)
            assertEquals(10, BucketCodec.getCodec(1).decodeStatementId(encode));
        else if (i < 8192)
            assertEquals(0b010000001010, BucketCodec.getCodec(1).decodeStatementId(encode));
        else if (i < 12288)
            assertEquals(0b100000001010, BucketCodec.getCodec(1).decodeStatementId(encode));
        else
            assertEquals(0b110000001010, BucketCodec.getCodec(1).decodeStatementId(encode));
    }
}

@Test
public void testAvoidSplitCombination() throws Exception {
    Configuration conf = new Configuration();
    JobConf job = new JobConf(conf);
    TableDesc tblDesc = Utilities.defaultTd;
    tblDesc.setInputFileFormatClass(TestSkipCombineInputFormat.class);
    PartitionDesc partDesc = new PartitionDesc(tblDesc, null);
    LinkedHashMap<Path, PartitionDesc> pt = new LinkedHashMap<>();
    pt.put(new Path("/tmp/testfolder1"), partDesc);
    pt.put(new Path("/tmp/testfolder2"), partDesc);
    MapredWork mrwork = new MapredWork();
    mrwork.getMapWork().setPathToPartitionInfo(pt);
    Path mapWorkPath = new Path("/tmp/" + System.getProperty("user.name"), "hive");
    Utilities.setMapRedWork(conf, mrwork, mapWorkPath);
    try {
        Path[] paths = new Path[2];
        paths[0] = new Path("/tmp/testfolder1");
