/**
 * Verifies the current database object is not locked if the table read is against different database
 * @throws Exception
 */
@Test
public void testSingleReadTable() throws Exception {
    // Setup
    SessionState.get().setCurrentDatabase("db1");
    List<HiveLock> expectedLocks = new ArrayList<HiveLock>();
    expectedLocks.add(new ZooKeeperHiveLock("default", new HiveLockObject(), HiveLockMode.SHARED));
    expectedLocks.add(new ZooKeeperHiveLock("default.table1", new HiveLockObject(), HiveLockMode.SHARED));
    DriverState driverState = new DriverState();
    DriverState driverInterrupted = new DriverState();
    driverInterrupted.abort();
    LockException lEx = new LockException(ErrorMsg.LOCK_ACQUIRE_CANCELLED.getMsg());
    when(mockLockManager.lock(anyListOf(HiveLockObj.class), eq(false), eq(driverState))).thenReturn(expectedLocks);
    when(mockLockManager.lock(anyListOf(HiveLockObj.class), eq(false), eq(driverInterrupted))).thenThrow(lEx);
    lenient().doNothing().when(mockLockManager).setContext(any(HiveLockManagerCtx.class));
    doNothing().when(mockLockManager).close();
    ArgumentCaptor<List> lockObjsCaptor = ArgumentCaptor.forClass(List.class);
    when(mockQueryPlan.getInputs()).thenReturn(createReadEntities());
    when(mockQueryPlan.getOutputs()).thenReturn(new HashSet<WriteEntity>());
    // Execute
    txnMgr.acquireLocks(mockQueryPlan, ctx, "fred", driverState);
    // Verify
    Assert.assertEquals("db1", SessionState.get().getCurrentDatabase());
    List<HiveLock> resultLocks = ctx.getHiveLocks();
    Assert.assertEquals(expectedLocks.size(), resultLocks.size());
    Assert.assertEquals(expectedLocks.get(0).getHiveLockMode(), resultLocks.get(0).getHiveLockMode());
    Assert.assertEquals(expectedLocks.get(0).getHiveLockObject().getName(), resultLocks.get(0).getHiveLockObject().getName());
    Assert.assertEquals(expectedLocks.get(1).getHiveLockMode(), resultLocks.get(1).getHiveLockMode());
    Assert.assertEquals(expectedLocks.get(0).getHiveLockObject().getName(), resultLocks.get(0).getHiveLockObject().getName());
    verify(mockLockManager).lock(lockObjsCaptor.capture(), eq(false), eq(driverState));
    List<HiveLockObj> lockObjs = lockObjsCaptor.getValue();
    Assert.assertEquals(2, lockObjs.size());
    Assert.assertEquals("default", lockObjs.get(0).getName());
    Assert.assertEquals(HiveLockMode.SHARED, lockObjs.get(0).mode);
    Assert.assertEquals("default/table1", lockObjs.get(1).getName());
    Assert.assertEquals(HiveLockMode.SHARED, lockObjs.get(1).mode);
    // Execute
    try {
        txnMgr.acquireLocks(mockQueryPlan, ctx, "fred", driverInterrupted);
        Assert.fail();
    } catch (LockException le) {
        Assert.assertEquals(le.getMessage(), ErrorMsg.LOCK_ACQUIRE_CANCELLED.getMsg());
    }
}

@Test
public void testDedupLockObjects() {
    List<HiveLockObj> lockObjs = new ArrayList<HiveLockObj>();
    String path1 = "path1";
    String path2 = "path2";
    HiveLockObjectData lockData1 = new HiveLockObjectData("query1", "1", "IMPLICIT", "drop table table1", conf);
    HiveLockObjectData lockData2 = new HiveLockObjectData("query1", "1", "IMPLICIT", "drop table table1", conf);
    // Start with the following locks:
    // [path1, shared]
    // [path1, exclusive]
    // [path2, shared]
    // [path2, shared]
    // [path2, shared]
    lockObjs.add(new HiveLockObj(new HiveLockObject(path1, lockData1), HiveLockMode.SHARED));
    String name1 = lockObjs.get(lockObjs.size() - 1).getName();
    lockObjs.add(new HiveLockObj(new HiveLockObject(path1, lockData1), HiveLockMode.EXCLUSIVE));
    lockObjs.add(new HiveLockObj(new HiveLockObject(path2, lockData2), HiveLockMode.SHARED));
    String name2 = lockObjs.get(lockObjs.size() - 1).getName();
    lockObjs.add(new HiveLockObj(new HiveLockObject(path2, lockData2), HiveLockMode.SHARED));
    lockObjs.add(new HiveLockObj(new HiveLockObject(path2, lockData2), HiveLockMode.SHARED));
    DummyTxnManager.dedupLockObjects(lockObjs);
    // After dedup we should be left with 2 locks:
    // [path1, exclusive]
    // [path2, shared]
    Assert.assertEquals("Locks should be deduped", 2, lockObjs.size());
    Comparator<HiveLockObj> cmp = new Comparator<HiveLockObj>() {

        @Override
        public int compare(HiveLockObj lock1, HiveLockObj lock2) {
            return lock1.getName().compareTo(lock2.getName());
        }
    };
    Collections.sort(lockObjs, cmp);
    HiveLockObj lockObj = lockObjs.get(0);
    Assert.assertEquals(name1, lockObj.getName());
    Assert.assertEquals(HiveLockMode.EXCLUSIVE, lockObj.getMode());
    lockObj = lockObjs.get(1);
    Assert.assertEquals(name2, lockObj.getName());
    Assert.assertEquals(HiveLockMode.SHARED, lockObj.getMode());
}

@Test
public void testLocking() throws LockException {
    HiveConf conf = new HiveConf();
    conf.set("hive.lock.numretries", "0");
    conf.set("hive.unlock.numretries", "0");
    EmbeddedLockManager manager = new EmbeddedLockManager();
    manager.setContext(new HiveLockManagerCtx(conf));
    String path1 = "database1/table1/x=100";
    String path2 = "database1/table1/x=200";
    String path3 = "database1/table2";
    String path4 = "database2";
    HiveLockObject path1sel1 = lockObj(path1, "select");
    HiveLock path1sel1Lock = manager.lock(path1sel1, HiveLockMode.SHARED, false);
    Assert.assertNotNull(path1sel1Lock);
    Assert.assertEquals(1, manager.getLocks(path1sel1, false, false).size());
    Assert.assertEquals(1, manager.getLocks(path1sel1, false, true).size());
    Assert.assertEquals(1, manager.getLocks(false, true).size());
    HiveLockObject path1up1 = lockObj(path1, "update");
    Assert.assertNull(manager.lock(path1up1, HiveLockMode.EXCLUSIVE, false));
    HiveLockObject path1sel2 = lockObj(path1, "select");
    HiveLock path1sel2Lock = manager.lock(path1sel2, HiveLockMode.SHARED, false);
    Assert.assertNotNull(path1sel2Lock);
    Assert.assertEquals(1, manager.getLocks(path1sel1, false, false).size());
    Assert.assertEquals(2, manager.getLocks(path1sel1, false, true).size());
    Assert.assertEquals(2, manager.getLocks(path1sel2, false, true).size());
    Assert.assertEquals(2, manager.getLocks(false, true).size());
    HiveLockObject path1up2 = lockObj(path1, "update");
    Assert.assertNull(manager.lock(path1up2, HiveLockMode.EXCLUSIVE, false));
    HiveLockObject path2sel1 = lockObj(path2, "select");
    HiveLock path2sel1Lock = manager.lock(path2sel1, HiveLockMode.SHARED, false);
    Assert.assertNotNull(path2sel1Lock);
    Assert.assertEquals(1, manager.getLocks(path1sel1, false, false).size());
    Assert.assertEquals(2, manager.getLocks(path1sel1, false, true).size());
    Assert.assertEquals(2, manager.getLocks(path1sel2, false, true).size());
    Assert.assertEquals(1, manager.getLocks(path2sel1, false, true).size());
    Assert.assertEquals(3, manager.getLocks(false, true).size());
    HiveLockObject path3sel = lockObj(path3, "select");
    HiveLock path3selLock = manager.lock(path3sel, HiveLockMode.SHARED, false);
    Assert.assertNotNull(path3selLock);
    Assert.assertEquals(1, manager.getLocks(path1sel1, false, false).size());
    Assert.assertEquals(2, manager.getLocks(path1sel1, false, true).size());
    Assert.assertEquals(2, manager.getLocks(path1sel2, false, true).size());
    Assert.assertEquals(1, manager.getLocks(path2sel1, false, true).size());
    Assert.assertEquals(1, manager.getLocks(path3sel, false, true).size());
    Assert.assertEquals(4, manager.getLocks(false, true).size());
    manager.unlock(path1sel1Lock);
    Assert.assertEquals(1, manager.getLocks(path1sel1, false, false).size());
    Assert.assertEquals(1, manager.getLocks(path1sel1, false, true).size());
    Assert.assertEquals(1, manager.getLocks(path1sel2, false, true).size());
    Assert.assertEquals(1, manager.getLocks(path2sel1, false, true).size());
    Assert.assertEquals(1, manager.getLocks(path3sel, false, true).size());
    Assert.assertEquals(3, manager.getLocks(false, true).size());
    manager.unlock(path1sel2Lock);
    Assert.assertEquals(1, manager.getLocks(path2sel1, false, true).size());
    Assert.assertEquals(1, manager.getLocks(path3sel, false, true).size());
    Assert.assertEquals(2, manager.getLocks(false, true).size());
    manager.unlock(path2sel1Lock);
    Assert.assertEquals(1, manager.getLocks(path3sel, false, true).size());
    Assert.assertEquals(1, manager.getLocks(false, true).size());
    manager.unlock(path3selLock);
    Assert.assertEquals(0, manager.getLocks(false, true).size());
    HiveLockObject path2up1 = lockObj(path2, "update");
    HiveLock path2up1Lock = manager.lock(path2up1, HiveLockMode.EXCLUSIVE, false);
    Assert.assertNotNull(path2up1Lock);
    Assert.assertEquals(1, manager.getLocks(path2up1, false, true).size());
    Assert.assertEquals(1, manager.getLocks(false, true).size());
    Assert.assertNull(manager.lock(path2up1, HiveLockMode.EXCLUSIVE, false));
    HiveLockObject path1sel3 = lockObj(path1, "select");
    HiveLockObject path2sel2 = lockObj(path2, "select");
    Assert.assertNotNull(manager.lock(path1sel3, HiveLockMode.SHARED, false));
    Assert.assertNull(manager.lock(path2sel2, HiveLockMode.SHARED, false));
    Assert.assertEquals(1, manager.getLocks(path2up1, false, true).size());
    Assert.assertEquals(1, manager.getLocks(path1sel3, false, true).size());
    Assert.assertEquals(2, manager.getLocks(false, true).size());
}

