        addDeltaFile(t, p, 21L, 22L, 2);
        addDeltaFile(t, p, 23L, 24L, 2);
        addDeltaFile(t, p, 21L, 24L, 4);
        partitions.add(p);
    }
    burnThroughTransactions("default", "camipc", 25);
    for (int i = 0; i < 10; i++) {
