    Assert.assertEquals(cleanerCyclesMinor + 10, Objects.requireNonNull(Metrics.getOrCreateTimer(CLEANER_CYCLE_KEY + "_" + CompactionType.MINOR.toString().toLowerCase())).getCount());
    for (int i = 0; i < 10; i++) {
        p = partitions.get(i);
        addBaseFile(t, p, 25L, 25, 26 + i);
        CompactionRequest rqst = new CompactionRequest("default", "camipc", CompactionType.MAJOR);
        rqst.setPartitionname("ds=today" + i);
        compactInTxn(rqst);
    }
