    }
}

@Test
public void testEqualityUDFWithSameTypeArgsSucceeds() throws UDFArgumentException {
    TypeInfo tleft = TypeInfoUtils.getTypeInfoFromObjectInspector(args.left);
    TypeInfo tRight = TypeInfoUtils.getTypeInfoFromObjectInspector(args.right);
    Assume.assumeTrue("Skip arguments with different types", tleft.equals(tRight));
    boolean unionInputs = tleft.getCategory().equals(ObjectInspector.Category.UNION) || tRight.getCategory().equals(ObjectInspector.Category.UNION);
    Assume.assumeFalse("Union types are not currently supported", unionInputs);
    List<GenericUDF> udfs = Arrays.asList(new GenericUDFOPEqual(), new GenericUDFOPEqualNS(), new GenericUDFOPNotEqual(), new GenericUDFOPEqualNS(), new GenericUDFIn());
    for (GenericUDF u : udfs) {
        u.initialize(new ObjectInspector[] { args.left, args.right });
    }
}

@Test
public void testBaseNonEqualityUDFWithNonPrimitiveTypeArgsThrowsException() {
    Assume.assumeTrue("Skip arguments with different categories", args.left.getCategory().equals(args.right.getCategory()));
    boolean allPrimitives = args.left.getCategory().equals(ObjectInspector.Category.PRIMITIVE) && args.right.getCategory().equals(ObjectInspector.Category.PRIMITIVE);
    Assume.assumeFalse("Skip primitive only arguments", allPrimitives);
    List<GenericUDF> udfs = Arrays.asList(new GenericUDFOPGreaterThan(), new GenericUDFOPLessThan(), new GenericUDFOPEqualOrGreaterThan(), new GenericUDFOPEqualOrLessThan());
    for (GenericUDF udf : udfs) {
        try {
            udf.initialize(new ObjectInspector[] { args.left, args.right });
            Assert.fail(udf.getUdfName() + " operator should not accept non primitive types [" + args.left.getCategory() + "," + args.right.getCategory() + "]");
        } catch (UDFArgumentException e) {
            boolean isValidMessage = e.getMessage().contains("not support MAP types") || e.getMessage().contains("not support LIST types") || e.getMessage().contains("not support STRUCT types") || e.getMessage().contains("not support UNION types");
            Assert.assertTrue("Unexpected message for " + udf.getUdfName(), isValidMessage);
        }
    }
}

