    String oldWarehouse = getWarehouseDir();
    String[] args = { "--hiveconf", "hive.strict.managed.tables=true", "-m", "automatic", "--modifyManagedTables", "--oldWarehouseRoot", oldWarehouse };
    HiveConf newConf = new HiveConf(hiveConf);
