    Object[][] casesWithSpaces = { { " 0", 0 }, { "0 ", 0 }, { " 0 ", 0 }, { " -128", -128 }, { "-128 ", -128 }, { "   -128   ", -128 }, { "  128", 128 }, { "128  ", 128 }, { "  128  ", 128 }, { " +128", 128 }, { "+128 ", 128 }, { "   +128    ", 128 }, { "   +128    ", 128 }, { "   -2147483648", -2147483648 }, { "-2147483648    ", -2147483648 }, { "   -2147483648   ", -2147483648 }, { "  2147483647", 2147483647 }, { "2147483647  ", 2147483647 }, { "  2147483647  ", 2147483647 }, { "   +2147483647", 2147483647 }, { "+2147483647   ", 2147483647 }, { "   +2147483647   ", 2147483647 } };
    String[] casesWithErrors = { "", "  ", "one", " one ", "123:", "123a", " 123a ", "a123", " a123 ", // Exceeds MAX_VALUE
    "2147483648", "-2147483649" };
    //
    // trim=false
