    Assert.assertEquals(0, fetchedDbs.size());
    fetchedDbs = new HashSet<>(client.getDatabases(catName, "*x"));
    Assert.assertEquals(0, fetchedDbs.size());
    // Check that dropping database from wrong catalog fails
