    Map<String, String> partitionSpecs = getPartitionSpec(partitions[1]);
    List<Partition> exchangedPartitions = client.exchange_partitions(partitionSpecs, sourceTable.getDbName(), sourceTable.getTableName(), destTable.getDbName(), destTable.getTableName());
    Assert.assertEquals(1, exchangedPartitions.size());
    String partitionName = Warehouse.makePartName(sourceTable.getPartitionKeys(), partitions[1].getValues());
    String exchangedPartitionName = Warehouse.makePartName(sourceTable.getPartitionKeys(), exchangedPartitions.get(0).getValues());
    Assert.assertEquals(partitionName, exchangedPartitionName);
    checkExchangedPartitions(sourceTable, destTable, Lists.newArrayList(partitions[1]));
    checkRemainingPartitions(sourceTable, destTable, Lists.newArrayList(partitions[0], partitions[2], partitions[3], partitions[4]));
}

@Test
public void testExchangePartitionsDestTableHasPartitions() throws Exception {
    // Create dest table partitions with custom locations
    createPartition(destTable, Lists.newArrayList("2019", "march", "15"), destTable.getSd().getLocation() + "/destPart1");
    createPartition(destTable, Lists.newArrayList("2019", "march", "22"), destTable.getSd().getLocation() + "/destPart2");
    Map<String, String> partitionSpecs = getPartitionSpec(partitions[1]);
    client.exchange_partitions(partitionSpecs, DB_NAME, sourceTable.getTableName(), DB_NAME, destTable.getTableName());
    checkExchangedPartitions(sourceTable, destTable, Lists.newArrayList(partitions[1]));
    checkRemainingPartitions(sourceTable, destTable, Lists.newArrayList(partitions[0], partitions[2], partitions[3], partitions[4]));
    // Check the original partitions of the dest table
    List<String> partitionNames = client.listPartitionNames(destTable.getDbName(), destTable.getTableName(), MAX);
    Assert.assertEquals(3, partitionNames.size());
    Assert.assertTrue(partitionNames.containsAll(Lists.newArrayList("year=2019/month=march/day=15", "year=2019/month=march/day=22")));
    Assert.assertTrue(metaStore.isPathExists(new Path(destTable.getSd().getLocation() + "/destPart1")));
    Assert.assertTrue(metaStore.isPathExists(new Path(destTable.getSd().getLocation() + "/destPart2")));
}

@Test
public void testExchangePartitionsYearSet() throws Exception {
    Map<String, String> partitionSpecs = getPartitionSpec(Lists.newArrayList("2017", "", ""));
    List<Partition> exchangedPartitions = client.exchange_partitions(partitionSpecs, sourceTable.getDbName(), sourceTable.getTableName(), destTable.getDbName(), destTable.getTableName());
    Assert.assertEquals(4, exchangedPartitions.size());
    List<String> exchangedPartNames = new ArrayList<>();
    for (Partition exchangedPartition : exchangedPartitions) {
        String partName = Warehouse.makePartName(sourceTable.getPartitionKeys(), exchangedPartition.getValues());
        exchangedPartNames.add(partName);
