@Test
public void testRuntimeStatHandling() throws Exception {
    List<RuntimeStat> rs0 = getRuntimeStats();
    assertNotNull(rs0);
    assertEquals(0, rs0.size());
    RuntimeStat stat = createStat(1);
    client.addRuntimeStat(stat);
    List<RuntimeStat> rs1 = getRuntimeStats();
    assertNotNull(rs1);
    assertEquals(1, rs1.size());
    assertArrayEquals(stat.getPayload(), rs1.get(0).getPayload());
    assertEquals(stat.getWeight(), rs1.get(0).getWeight());
    // server sets createtime
    assertNotEquals(stat.getCreateTime(), rs1.get(0).getCreateTime());
    client.addRuntimeStat(createStat(2));
    client.addRuntimeStat(createStat(3));
    client.addRuntimeStat(createStat(4));
    List<RuntimeStat> rs2 = getRuntimeStats();
    assertEquals(4, rs2.size());
}

@Test
public void testCleanup() throws Exception {
    ObjectStore objStore = new ObjectStore();
    objStore.setConf(metaStore.getConf());
    objStore.deleteRuntimeStats(0);
    objStore.addRuntimeStat(createStat(1));
    TimeUnit.SECONDS.sleep(6);
    objStore.addRuntimeStat(createStat(2));
    int deleted = objStore.deleteRuntimeStats(5);
    assertEquals(1, deleted);
    List<RuntimeStat> all = getRuntimeStats();
    assertEquals(1, all.size());
    assertEquals(2, all.get(0).getWeight());
}

@Test
public void testReading() throws Exception {
    ObjectStore objStore = new ObjectStore();
    objStore.setConf(metaStore.getConf());
    objStore.deleteRuntimeStats(0);
    objStore.addRuntimeStat(createStat(1));
    Thread.sleep(1000);
    objStore.addRuntimeStat(createStat(2));
    Thread.sleep(1000);
    objStore.addRuntimeStat(createStat(3));
    List<RuntimeStat> g0 = client.getRuntimeStats(3, -1);
    assertEquals(1, g0.size());
    assertEquals(3, g0.get(0).getWeight());
    int ct = g0.get(0).getCreateTime();
    List<RuntimeStat> g1 = client.getRuntimeStats(3, ct);
    assertEquals(2, g1.size());
    assertEquals(2, g1.get(0).getWeight());
    assertEquals(1, g1.get(1).getWeight());
    int ct1 = g1.get(1).getCreateTime();
    List<RuntimeStat> g2 = client.getRuntimeStats(3, ct1);
    assertEquals(0, g2.size());
}

/**
 * This test creates and queries a table and then drops it. Good for testing the happy path
 */
@Test
public void testCreateGetDeleteTable() throws Exception {
    // Try to create a table with all of the parameters set
    Table table = getTableWithAllParametersSet();
    client.createTable(table);
    table.unsetId();
    Table createdTable = client.getTable(table.getDbName(), table.getTableName());
    // The createTime will be set on the server side, so the comparison should skip it
    table.setCreateTime(createdTable.getCreateTime());
    // The extra parameters will be added on server side, so check that the required ones are
    // present
    for (String key : table.getParameters().keySet()) {
        Assert.assertEquals("parameters are the same", table.getParameters().get(key), createdTable.getParameters().get(key));
    }
    // Reset the parameters, so we can compare
    table.setParameters(createdTable.getParameters());
    table.setCreationMetadata(createdTable.getCreationMetadata());
    table.setWriteId(createdTable.getWriteId());
    Assert.assertTrue(createdTable.isSetId());
    createdTable.unsetId();
    Assert.assertEquals("create/get table data", table, createdTable);
    // Check that the directory is created
    Assert.assertTrue("The directory should not be created", metaStore.isPathExists(new Path(createdTable.getSd().getLocation())));
    client.dropTable(table.getDbName(), table.getTableName(), true, false);
    try {
        client.getTable(table.getDbName(), table.getTableName());
        Assert.fail("Expected a NoSuchObjectException to be thrown");
    } catch (NoSuchObjectException exception) {
        // Expected exception
    }
}

