    alteredTable = client.getTable(newTable.getDbName(), newTable.getTableName());
    Assert.assertEquals("The table data should be changed", newTable, alteredTable);
    partitions = client.listPartitions(originalTable.getDbName(), originalTable.getTableName(), (short) -1);
    for (Partition partition : partitions) {
        Assert.assertEquals("Partition columns should be changed", 4, partition.getSd().getCols().size());
    }
    // Run using environment context with cascade
    cols.add(new FieldSchema("new_col_3", "int", null));
    EnvironmentContext context = new EnvironmentContext();
    context.putToProperties(StatsSetupConst.CASCADE, "true");
    client.alter_table_with_environmentContext(originalTable.getDbName(), originalTable.getTableName(), newTable, context);
    alteredTable = client.getTable(newTable.getDbName(), newTable.getTableName());
    Assert.assertEquals("The table data should be changed", newTable, alteredTable);
    partitions = client.listPartitions(originalTable.getDbName(), originalTable.getTableName(), (short) -1);
    for (Partition partition : partitions) {
        Assert.assertEquals("Partition columns should be changed", 5, partition.getSd().getCols().size());
    }
}

