    createConfFile("metastore-site.xml", true, "METASTORE_HOME", instaMap("test.long", "23"));
    conf = MetastoreConf.newMetastoreConf();
    String dump = MetastoreConf.dumpConfig(conf);
    Assert.assertThat(dump, new StringContains("Used metastore-site file: file:/"));
    Assert.assertThat(dump, new StringContains("Key: <test.long> old hive key: <hive.test.long>  value: <23>"));
    Assert.assertThat(dump, new StringContains("Key: <test.str> old hive key: <hive.test.str>  value: <defaultval>"));
    Assert.assertThat(dump, new StringEndsWith("Finished MetastoreConf object.\n"));
    // Make sure the hidden keys didn't get published
    Assert.assertThat(dump, CoreMatchers.not(new StringContains(ConfVars.PWD.getVarname())));
}

/**
 * Test class names hardcoded in MetastoreConf.
 * MetastoreConf uses several hard-coded class names. If one of these classes is renamed or
 * moved to a different package we want to be able to catch this. So we compare expected
 * class name with the actual one.
 */
@Test
public void testClassNames() {
    Assert.assertEquals(MetastoreConf.DEFAULT_STORAGE_SCHEMA_READER_CLASS, DefaultStorageSchemaReader.class.getName());
    Assert.assertEquals(MetastoreConf.HIVE_ALTER_HANDLE_CLASS, HiveAlterHandler.class.getName());
    Assert.assertEquals(MetastoreConf.MATERIALZIATIONS_REBUILD_LOCK_CLEANER_TASK_CLASS, MaterializationsRebuildLockCleanerTask.class.getName());
    Assert.assertEquals(MetastoreConf.METASTORE_TASK_THREAD_CLASS, MetastoreTaskThread.class.getName());
    Assert.assertEquals(MetastoreConf.RUNTIME_STATS_CLEANER_TASK_CLASS, RuntimeStatsCleanerTask.class.getName());
    Assert.assertEquals(MetastoreConf.EVENT_CLEANER_TASK_CLASS, EventCleanerTask.class.getName());
    Assert.assertEquals(MetastoreConf.METASTORE_DELEGATION_MANAGER_CLASS, MetastoreDelegationTokenManager.class.getName());
    Assert.assertEquals(MetastoreConf.ACID_HOUSE_KEEPER_SERVICE_CLASS, AcidHouseKeeperService.class.getName());
    Assert.assertEquals(MetastoreConf.ACID_TXN_CLEANER_SERVICE_CLASS, AcidTxnCleanerService.class.getName());
    Assert.assertEquals(MetastoreConf.ACID_OPEN_TXNS_COUNTER_SERVICE_CLASS, AcidOpenTxnsCounterService.class.getName());
}

