            assertTrue(fieldSchemasFull.contains(fs));
        }
    } catch (Exception e) {
        System.err.println(StringUtils.stringifyException(e));
        System.err.println("testComplexTable() failed.");
        throw e;
    } finally {
        client.dropTable(dbName, tblName);
