    expectedMap = new HashMap<String, String>() {

        {
            put("totalSize", "1024");
            put("numRows", "10");
            put("rawDataSize", "3243234");
            put("COLUMN_STATS_ACCURATED", "dummy");
            put("numFiles", "2");
            put("transient_lastDdlTime", "1537487124");
            put("testBucketing_version", "2");
            put("numFilesErasureCoded", "0");
        }
