    excludePatterns = Arrays.asList(MetastoreConf.getTrimmedStringsVar(testConf, MetastoreConf.ConfVars.EVENT_NOTIFICATION_PARAMETERS_EXCLUDE_PATTERNS));
    testMapFilter(testMap, excludePatterns);
    assertThat(getTestParamMap(), is(testMap));
}

