@Test
public void testErrorConditions() throws Exception {
    DiskRangeList d510 = new DiskRangeList(0, 10);
    d510.insertPartBefore(new DiskRangeList(0, 5));
    DiskRangeList d1015 = d510.insertAfter(new DiskRangeList(10, 15));
    try {
        // The arg is self.
        d510.replaceSelfWith(d510);
        fail();
    } catch (AssertionError error) {
    }
    DiskRangeList existing = new DiskRangeList(0, 10);
    existing.insertPartBefore(new DiskRangeList(0, 5));
    try {
        // The arg is part of another list.
        d510.replaceSelfWith(existing);
        fail();
    } catch (AssertionError error) {
    }
    try {
        // Not sequential with previous.
        d510.replaceSelfWith(new DiskRangeList(4, 10));
        fail();
    } catch (AssertionError error) {
    }
    try {
        // Not sequential with next.
        d510.replaceSelfWith(new DiskRangeList(5, 11));
        fail();
    } catch (AssertionError error) {
    }
    try {
        // The arg is self.
        d510.insertPartBefore(d510);
        fail();
    } catch (AssertionError error) {
    }
    existing = new DiskRangeList(5, 7);
    existing.insertPartBefore(new DiskRangeList(5, 6));
    try {
        // The arg is part of another list.
        d510.insertPartBefore(existing);
        fail();
    } catch (AssertionError error) {
    }
    try {
        // Not a part.
        d510.insertPartBefore(new DiskRangeList(3, 4));
        fail();
    } catch (AssertionError error) {
    }
    try {
        // Not sequential with previous.
        d510.insertPartBefore(new DiskRangeList(4, 6));
        fail();
    } catch (AssertionError error) {
    }
    try {
        // The arg is self.
        d510.insertAfter(d510);
        fail();
    } catch (AssertionError error) {
    }
    existing = new DiskRangeList(15, 20);
    existing.insertAfter(new DiskRangeList(20, 25));
    try {
        // The arg is part of another list.
        d1015.insertAfter(existing);
        fail();
    } catch (AssertionError error) {
    }
    try {
        // Not sequential.
        d1015.insertAfter(new DiskRangeList(14, 20));
        fail();
    } catch (AssertionError error) {
    }
    d1015.insertAfter(new DiskRangeList(20, 25));
    try {
        // Not sequential with next.
        d1015.insertAfter(new DiskRangeList(15, 21));
        fail();
    } catch (AssertionError error) {
    }
    try {
        // Not a part.
        d1015.insertPartAfter(new DiskRangeList(16, 20));
        fail();
    } catch (AssertionError error) {
    }
    try {
        // Not a part.
        d1015.insertPartAfter(new DiskRangeList(9, 11));
        fail();
    } catch (AssertionError error) {
    }
    try {
        // Not sequential with next.
        d1015.setEnd(21);
        fail();
    } catch (AssertionError error) {
    }
}

