    byte[] val2 = new byte[] { 1, 2, 3, 4, 5 };
    byte[] val3 = new byte[] { 1, 2, 3, 4, 5, 6 };
    assertFalse(bf.test(val));
    assertFalse(bf.test(val1));
    assertFalse(bf.test(val2));
    assertFalse(bf.test(val3));
